var N64_EMU = {"label":"Nintendo 64","order":["readme","00-machine","05-memory","10-cpu","20-rsp","30-rdp","40-vi","50-ai","60-pi","70-si-pif","80-saves","90-cartridges","95-scores"],"titles":{"readme":"How this page is set out","00-machine":"The machine","05-memory":"Main memory","10-cpu":"The processor","20-rsp":"The RSP","30-rdp":"The RDP","40-vi":"The VI","50-ai":"The AI and the sound check","60-pi":"The PI","70-si-pif":"The SI and the PIF","80-saves":"Save memory","90-cartridges":"What a cartridge holds","95-scores":"The scores"},"units":{"readme":"<section class=\"sect n64emu-chapter\" id=\"n64emu-readme-sect\"><h3 class=\"sect-h\" id=\"n64emu-readme\">How this page is set out</h3>\n<p>This page says how the Nintendo 64 emulator works and how it was measured, one part of the console at a time. Every chapter has the same four sections: what the emulator does, how it was measured, what two PAL consoles said, and what is still not known. The last chapter gives the scores of the public test suites and lists the test cartridges written for this emulator.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-readme--the-chapters\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-readme-s1\">1. The chapters</h4>\n<ul class=\"gbemu-bullets\"><li><a href=\"#n64emu-00-machine\">The machine</a>: the console as a whole, and the real consoles the measurements come from.</li><li><a href=\"#n64emu-05-memory\">Main memory</a>: the memory chips and how they are started.</li><li><a href=\"#n64emu-10-cpu\">The processor</a>: the processor and its timing.</li><li><a href=\"#n64emu-20-rsp\">The RSP</a>: the processor that works beside the main one on pictures and sound.</li><li><a href=\"#n64emu-30-rdp\">The RDP</a>: the part that draws, with the hidden bits of memory it uses.</li><li><a href=\"#n64emu-40-vi\">The VI</a>: the part that sends the picture to the television.</li><li><a href=\"#n64emu-50-ai\">The AI and the sound check</a>: the part that sends the sound out.</li><li><a href=\"#n64emu-60-pi\">The PI</a>: the bus to the cartridge.</li><li><a href=\"#n64emu-70-si-pif\">The SI and the PIF</a>: the controllers, their paks, and the chip that starts the console and speaks to them.</li><li><a href=\"#n64emu-80-saves\">Save memory</a>: the chips that keep a game's saves.</li><li><a href=\"#n64emu-90-cartridges\">What a cartridge holds</a>: lockout chips, boot code and the table of games.</li><li><a href=\"#n64emu-95-scores\">The scores</a>: the public test suites, and our own test cartridges.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-readme--how-sure-each-statement-is\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-readme-s2\">2. How sure each statement is</h4>\n<p>Each statement says in words how it is known.</p>\n<div class=\"gbemu-scroll\"><table class=\"gbemu-table\"><thead><tr><th>Words</th><th>Meaning</th></tr></thead><tbody><tr><td>measured on hardware</td><td>read from the printout of one of the runs on a real console</td></tr><tr><td>recorded on hardware by its authors</td><td>a test written by others, whose expected results its authors took from consoles</td></tr><tr><td>measured</td><td>counted by an instrument of this emulator's own, with its denominator</td></tr><tr><td>tuned</td><td>a constant chosen so that measured cases come out right, where the mechanism is not known</td></tr><tr><td>agrees with another emulator</td><td>nothing better is known, and the page says so plainly</td></tr><tr><td>not established</td><td>not known</td></tr></tbody></table></div></section>","00-machine":"<section class=\"sect n64emu-chapter\" id=\"n64emu-00-machine-sect\"><h3 class=\"sect-h\" id=\"n64emu-00-machine\">The machine</h3>\n<p>This is an emulator of the Nintendo 64 built one chip at a time. Each part of the console is emulated as the console does it, at the level of its registers and its timing, and nothing in it is written for any one game. This page says, part by part, what the emulator does, how that was measured, and what is still not known. This first chapter is about the machine as a whole and about the real consoles the measurements come from.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-00-machine--what-the-emulator-does\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-00-machine-s1\">1. What the emulator does</h4>\n<ul class=\"gbemu-bullets\"><li>It emulates the processor, the RSP, the RDP, the VI, the AI, the PI, the SI with the PIF, and main memory, each as a part of its own with its own registers. The later chapters take them one at a time.</li><li>All parts share one clock, so the time one part takes is counted in the same units as every other's.</li><li>It starts the way a console starts. The boot firmware hands over, the cartridge's own boot code sets main memory up chip by chip, and only then does the program begin. Nothing is set up for the program in advance.</li><li>It can run as a PAL, an NTSC or an MPAL console. The television type changes the length of a picture line, the number of lines, the clock of the sound output and what the boot firmware hands to a program.</li><li>It runs in a web browser as WebAssembly. The same source also builds as a program for a desktop computer, and the two are held to give the same results.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> A shortcut that is right for most games is wrong for the ones that lean on exactly the behaviour the shortcut skips. Emulating each chip as it is costs speed and removes that whole class of faults.</p></div>\n<span class=\"n64emu-alt\" id=\"n64emu-00-machine--how-it-was-measured\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-00-machine-s2\">2. How it was measured</h4>\n<p>Three kinds of instrument are used, and each chapter says which stands behind each statement.</p>\n<ul class=\"gbemu-bullets\"><li><b>Test programs written by others, recorded on hardware by their authors.</b> The largest is the system test suite. The emulator passes 4,637 of 4,637 of its checks.</li><li><b>Probes written for this emulator.</b> A probe is a small program that asks the machine one question and prints the answer. Each probe runs on the emulator and on a real console, and the two printouts are compared line by line.</li><li><b>A second emulator, as a second opinion</b> where no test and no console run settles a question. Statements that rest only on that are marked as agreeing with another emulator.</li></ul>\n<p>Every check is also shown to fail once. For each rule a check is meant to guard, a copy of the emulator is built with that rule wrong on purpose, and the check has to notice.</p>\n<p>The console runs were made on two PAL consoles sold in Australia. Both main boards are marked NUS-CPU(P)-01, read from the board's own printing beside the cartridge slot with the case open. The tests reach a console on a flash cartridge that takes a test program over USB and passes back what the program prints. Each printout is kept exactly as it arrived, and a register lists every run with the printout's size and hash, the console, the memory fitted and the test program sent. The register holds 211 runs. The test programs that ran are kept as well, each under its hash, and so are the scripts that drove the runs and timed them: anyone with a console and the same cartridge can make the runs again and set the result beside ours.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-00-machine--what-two-pal-consoles-said\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-00-machine-s3\">3. What two PAL consoles said</h4>\n<ul class=\"gbemu-bullets\"><li>With 8 MiB of memory fitted, none of the 4,637 checks of the system test suite failed on either console. The emulator had the same result before the consoles were tried.</li><li>The same suite expects 8 MiB. Run with 4 MiB it fails three of its tests and stops, on both consoles, in the same words and at the same place as on the emulator. That outcome was written down before the first console run.</li><li>The two consoles agree with each other. Several probes gave the same printout on both, byte for byte. Where figures differ between them, they differ by a few counts, and each chapter gives the range.</li><li>Where a console contradicted the emulator, the emulator was changed to the console. The chapters name each such place.</li></ul>\n<p>One finding is about the method and not about the console. The flash cartridge is powered through its USB cable and stays on while the console is off, and a console switched off in that state does not forget everything. A mark left in the processor by one program was still there for the next program after the console had been off for about two and a quarter minutes with the cable in. With the cable out for 74 seconds it was gone. So a test that reads what a program finds at start can be reading what the run before it left behind, and the register says for each such run what came before it. A later session therefore began three of those tests from a cold console, the cable out for between one minute and some hours. What they read at start was what the warm runs had read, but for the settings each memory chip gives itself, which a cold console sets differently from a warm one.</p>\n<p>Everything above was measured on PAL consoles. The processor, the RSP, the RDP and the buses do not look at the television type, so those results are expected to hold on an NTSC console, but none has been measured.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-00-machine--what-is-not-established\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-00-machine-s4\">4. What is not established</h4>\n<ul class=\"gbemu-bullets\"><li>Nothing has been measured on an NTSC or an MPAL console. Statements about those types rest on test programs recorded on NTSC consoles by their authors, or on agreement with another emulator.</li><li>What exactly a switched-off console keeps while the cartridge is powered is not known. One mark in the processor's status register was followed. Whether more is kept has not been tested.</li><li>No result from playing a game is claimed on this page.</li></ul></section>","05-memory":"<section class=\"sect n64emu-chapter\" id=\"n64emu-05-memory-sect\"><h3 class=\"sect-h\" id=\"n64emu-05-memory\">Main memory</h3>\n<p>Main memory is a chain of memory chips behind a part called the RI. After power-on none of them answers. A program's boot code has to wake them one at a time, tell each where it sits, and find the electric current at which its data comes back whole. Only then is there any memory to run in.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-05-memory--what-the-emulator-does\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-05-memory-s1\">1. What the emulator does</h4>\n<ul class=\"gbemu-bullets\"><li>After power-on no memory answers. A read gives zero and a write is lost, for the processor and for every other part alike.</li><li>The cartridge's own boot code sets memory up, as on a console. It resets the chips, sets their delays, gives each chip its place, switches it on and searches for the current at which the chip answers. The emulator runs that code as it is and gives it chips to find.</li><li>The console holds two chips of 2 MiB. The Expansion Pak adds one chip of 4 MiB, which answers at four places.</li><li>Each chip needs a least current before its data comes back whole. A chip in the console and the Expansion Pak's chip have different ones.</li><li>A chip's row register shows the row it has open in each of its megabytes.</li><li>A read that no chip answers gives zero and leaves no mark. A write that no chip hears leaves three marks in the RI's error register.</li><li>With 4 MiB fitted, the megabytes above them read zero and take no write.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> A program sizes memory by what answers. A machine that hands every program 8 MiB already set up cannot run a boot code as it is, and cannot show what a game does on a console with 4 MiB.</p></div>\n<span class=\"n64emu-alt\" id=\"n64emu-05-memory--how-it-was-measured\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-05-memory-s2\">2. How it was measured</h4>\n<ul class=\"gbemu-bullets\"><li>A check drives the RI and the chips one rule at a time, from outside the machine. 33 of 33 rules hold.</li><li>A probe written for this emulator prints the RI's registers, every register of every chip, and what each megabyte answers. It runs four times on the emulator, with 4 MiB and 8 MiB, from a cold start and after the reset button, and 1,032 values are held to what is expected of them.</li><li>The system test suite has a build for 4 MiB. Started with memory not set up, 736 of 736 processor tests and 71 of 71 tests of memory, the buses and the PIF pass.</li><li>The test build can also start a program with no boot code. That start is held against what two boot codes leave behind in the RI and the chips: 308 of 308 values.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-05-memory--what-two-pal-consoles-said\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-05-memory-s3\">3. What two PAL consoles said</h4>\n<p>The probe ran on both consoles, with 4 MiB and with 8 MiB. The first console's main board is marked NUS-CPU(P)-01; the second console's case has not been opened.</p>\n<ul class=\"gbemu-bullets\"><li>Before the consoles were tried, the emulator's printout differed from the first console's in 9 of 47 lines. Every one of those lines was a value in the RI's registers or inside a chip, and the emulator was changed to the consoles in each.</li><li>The consoles corrected five things. The Expansion Pak is one chip and not two. A read that no chip answers leaves no mark. The RI's error register reads all three marks after the boot code's search for one chip more. A chip's row register shows the rows it has open. One bit of a chip's mode register, the one that turns its own regulation on, does not read back.</li><li>After start-up each chip regulates its own current, and its mode register reads back the step it has settled at. The four chips inside the two consoles read 26 to 32 and the Expansion Pak's chip read 24 or 25, a step more or less from one read to the next. The emulator's chips read a value inside those ranges, and the check accepts the range and nothing wider.</li><li>The system test suite as fetched expects 8 MiB. With 4 MiB it fails three tests and stops, in the same words on both consoles as on the emulator.</li><li>With 8 MiB fitted the probe's megabyte lines and the suite agree with the emulator as it was.</li></ul>\n<p>Memory start-up does not look at the television type, so these results are expected to hold on an NTSC console. None has been measured.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-05-memory--what-is-not-established\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-05-memory-s4\">4. What is not established</h4>\n<ul class=\"gbemu-bullets\"><li>What makes each chip settle at its own step. The emulator gives a chip in the console and the Expansion Pak's chip each a least current, tuned so that the boot code's search ends inside the range the consoles gave. A probe that steps a chip's current by hand has been written and has not been run on a console; it would measure the least current itself.</li><li>A chip's refresh counter runs on a console, so two reads of it differ. In the emulator it stands still.</li><li>What a write to a chip's row register does. No test writes there.</li><li>What the chips and the RI hold after the reset button. No console has been asked; the emulator takes what a cold start leaves to stay.</li><li>Chips of another maker. Both consoles and the Expansion Pak gave the same maker's number.</li></ul></section>","10-cpu":"<section class=\"sect n64emu-chapter\" id=\"n64emu-10-cpu-sect\"><h3 class=\"sect-h\" id=\"n64emu-10-cpu\">The processor</h3>\n<p>The processor is the chip that runs the game's program, one instruction after another. Games written for the console lean on how long its instructions take, on its two small caches and on the wait each time it reaches out to memory, so the emulator counts all three as the chip does.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-10-cpu--what-the-emulator-does\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-10-cpu-s1\">1. What the emulator does</h4>\n<ul class=\"gbemu-bullets\"><li>It runs every instruction of the processor and counts the time each one takes, in the processor's own clock cycles. Most take one cycle. A 32-bit divide takes 37 cycles, and the instruction after a load waits a cycle if it names the register just loaded.</li><li>It keeps the two instructions behind the running one already fetched, as the chip's pipeline does. A program that changes its own code sees the old instructions for exactly that long.</li><li>It has both caches, line for line, and nothing keeps them in step with memory behind the program's back. An instruction that works on a cache takes from 5 to 15 cycles by what it finds in the line.</li><li>A read from main memory that does not go through a cache takes 32 cycles. A line of data brought into the cache hands the processor its word first and goes on arriving behind it. A store that does not go through a cache waits in a buffer of four while the processor runs on.</li><li>A line of the data cache goes back to memory whole: all 16 bytes, the ones the program never stored through the cache too. A program that stores into memory past the cache, into bytes a dirty line also covers, loses those stores when the line is written back.</li><li>Entering an exception takes between 3 and 7 cycles by where in the pipeline it was found, and an interrupt takes 5 cycles.</li><li>An interrupt of the RCP does not reach the processor at once. One that a store asks the RSP for calls the processor away 12 cycles of the RCP's clock after the store takes the bus, and one that is let through the interrupt mask 7 cycles after. A request that is taken back again before the processor has seen it still arrives: it is not lost on the way.</li><li>A store that does not go through a cache keeps the bus from the next store for a while that goes by where it lands: 2, 7 or 11 cycles of the RCP's clock for the interrupt registers, another part's register and main memory. The interrupt registers answer a read in 7 cycles of that clock, half of what another part's register takes.</li><li>A cache line that is filled while the memory's repeat mode is armed is not given the line as memory holds it: the memory chips send fewer pieces than the line has words, and the last piece stands for the rest.</li><li>Main memory is not the processor's alone. At the start of every line of the picture the memory chips are refreshed, and for 78 cycles main memory answers nothing. While a picture is being sent the VI reads memory too, and the processor's reads wait their turn.</li><li>A 32-bit divide whose divisor is not a proper 32-bit value gives what the chip's divider gives, step by step: a divider that adds or subtracts 32 times, with a partial remainder 67 bits wide, and steers by the wrong sign bit.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> A game that waits by counting instructions, or that changes memory under a cache, or that divides numbers it never cleaned up, works on a console because of these details. An emulator that leaves them out runs most games and breaks those.</p></div>\n<span class=\"n64emu-alt\" id=\"n64emu-10-cpu--how-it-was-measured\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-10-cpu-s2\">2. How it was measured</h4>\n<ul class=\"gbemu-bullets\"><li><b>The system test suite's timing level</b>, recorded on hardware by its authors on an NTSC console. Run as an NTSC console the emulator passes 24 of 26 of its timing tests and 12 of 12 of its cycle tests. The suite also counts the checks inside those tests: the emulator passes 1,607 of the 1,617 checks of the two levels, and the 10 it fails are in the two tests it does not pass.</li><li><b>The bus timing bench</b>, with its author's figures from an NTSC console. Run as an NTSC console the emulator comes within the bench's own allowance on 39 of 39 of its rows that are counted in processor cycles.</li><li><b>The processor time probe</b>, written for this emulator. It times small pieces of code against the processor's own counter and prints 45 lines of answers, and one more group about the memory refresh.</li><li><b>The divide probe</b>, written for this emulator. It prints 3,472 answers of the divide instruction, most of them for divisors no public source explains.</li><li><b>The data cache line probe</b>, written for this emulator. It walks one line of the data cache through a store through the cache, stores past the cache into the same bytes, and each way a line goes to memory, and prints 36 lines of what memory holds afterwards. Copies of the emulator made wrong on purpose, each treating such a line another way, are told apart by it: 3 of 3 are noticed and named.</li><li><b>The memory watch</b>, an instrument inside the emulator. It lists every write that reaches a chosen 16 bytes of memory, by the road it took: through the cache, past it, a line written back, or a part of the machine writing by itself. On the probe's run it lists 588 of them, and a second instrument that reads memory itself after every instruction finds what the watch says each time.</li><li>Each rule built from the console runs was also shown to matter: 10 of 10 copies of the emulator made wrong on purpose, one rule each, are noticed by the check that holds the emulator to the consoles.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-10-cpu--what-two-pal-consoles-said\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-10-cpu-s3\">3. What two PAL consoles said</h4>\n<p>The two probes and the bench ran on two PAL consoles, and so did the suite's timing level.</p>\n<ul class=\"gbemu-bullets\"><li><b>The probe's lines.</b> Before anything was changed, 17 of the 45 lines were the emulator's. The consoles corrected the rest. An instruction that works on a cache takes 5 to 15 cycles where the emulator had 1. An exception found while fetching takes 7 cycles where it had 3. An interrupt takes 5 cycles where it had 4. An interrupt that a store asks for reaches the processor more than 13 cycles after the store. Run as a PAL console the emulator now prints 43 of 45 lines exactly as the consoles did. The other two stay within two steps of the consoles' figure, and move with where the memory refresh falls against the program. These should hold on an NTSC console: they are the processor's own, and the processor does not look at the television type.</li><li><b>The memory refresh.</b> With the VI off, all but 37 to 41 of 2,048 single reads of memory took the usual time on the consoles, and the rest waited up to 82 cycles more. A loop of reads then runs at 39.47 cycles a turn on the consoles and on the emulator. The refresh should be there on an NTSC console too, with that console's own line length.</li><li><b>The bench.</b> On both consoles a store that misses the cache takes 40 cycles where the bench's author, on an NTSC console, has 35. The emulator follows our consoles when it runs as a PAL console and the author's when it runs as an NTSC one. As a PAL console it is inside the two consoles' range on 31 of 39 rows however the rest of the machine is timed. The other eight stay within three cycles of that range and move with where the memory refresh falls against the program, which they never do on a console.</li><li><b>The interrupt's road.</b> Three more probes ran on one of the consoles. With every instruction already in the cache, a row of idle instructions stops 19, 19 and 18 instructions after the store that asks for the interrupt, by where the store falls against the RCP's clock; the emulator stopped it three to four instructions sooner. A read of the interrupt registers before the store fixes that place, and then every one of eight tries agrees. The same probes gave the interrupt its 5 cycles, the store its time on the bus, and the interrupt registers their short read. With those built the emulator prints 297 of 297 of the lines it is held to as the console did, in two runs of the probe, and 24 of 24 of the earlier probe's. These should hold on an NTSC console: they are the processor's and the RCP's own clocks. A fourth probe asked what those left open, and the emulator prints 123 of 123 of the lines it is held to there. Two things it measured are not built yet: a cache line written back keeps the bus busy for a while after the processor has gone on, and a read straight behind a store to the interrupt registers falls a cycle or two from where the emulator has it. A third is built since: a line of instructions fetched from another row of memory costs one RCP cycle more than the emulator charged, and a later probe showed why a public bench had read it a cycle shorter.</li><li><b>A cache line filled with the repeat mode armed.</b> A probe filled lines of both caches with the memory's repeat mode armed for five lengths and read back what the caches were given. The emulator now gives the console's words in 30 of 30 armed cases. No game arms that mode while it plays.</li><li><b>The divider.</b> The two consoles gave the same 3,424 answers for divisors whose two sign bits disagree, and none was the emulator's. The divider's own steps give every one: the emulator now prints 3,472 of 3,472 answers as the consoles did. This should hold on an NTSC console: the divider is the processor's.</li><li><b>A line written back over memory.</b> A test of the RSP copies its program into memory past the cache, into bytes that a dirty line of the cache also covers. On the emulator the line is later written back over the start of the copy, and the test stops; on a console the same file ran for an hour. The data cache line probe then ran twice on one of the two consoles and printed 36 of 36 lines as the emulator prints them, both times: a console loses such stores too. The console's run of the test was another run of the same file. With no debug text window on the cartridge the test's library never asks for a buffer for its text, the copy lies 1,088 bytes lower, and no line of that number is brought in before the copy is used. Run without the window, the emulator runs the test as the console did. This should hold on an NTSC console: the caches are the processor's own.</li><li><b>The suite's tests of a read's time.</b> Both consoles fail 3 of the suite's 26 timing tests, which its authors' NTSC console passes. As a PAL console the emulator gives the consoles' verdict on 23 of those 26: it does not yet make the two that time a read beside a picture fail as the consoles do, and it fails one that times a line of data with the picture off, which they pass.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-10-cpu--what-is-not-established\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-10-cpu-s4\">4. What is not established</h4>\n<ul class=\"gbemu-bullets\"><li>Whether the second console, and an NTSC console, print the same lines of the data cache line probe. One run on each would settle it.</li><li>Whether a store that misses takes longer on every PAL console or only on consoles of this make. The bench on an NTSC console, or on a PAL console of another make, would settle it.</li><li>How the time from a store to the interrupt splits between the store landing, the interrupt registers and the way to the processor. Only the sums are measured. A part that raises its interrupt at a moment the processor knows, with no store of the processor's before it, would give the split.</li><li>Whether the second console and an NTSC console print the same lines of the three probes of the interrupt's road. One run of each would settle it.</li><li>What a line of instructions fetched after a miss costs when the memory chip must change its row, and where the processor stands afterwards. One row of the bench stands a step off the consoles for want of it. A probe line that lets the processor run into a line that is not in the cache would settle it.</li><li>What the data cache costs the bus after the processor has gone on: on the console a store behind a line that had to be written back waits far longer than on the emulator.</li><li>When exactly the VI reads memory within a line. The share it takes from the processor is tuned to two console runs; the VI's own chapter has what is known.</li><li>Where the first refresh falls against a program. A console leaves it to chance, so counts that depend on it are held to a range.</li><li>The time of the cache instructions the probe does not reach, and of the divide instructions other than the 32-bit signed one for divisors that are not proper values.</li><li>Whether the second console and an NTSC console show the wait behind a store through the data cache as the first console does. On that console a load or a store right behind such a store waits one cycle, whether it goes through the cache, as the processor's manual says, or is made without it, which the manual does not say. A probe of pairs of instructions showed it in two runs, and the emulator has 154 of its 168 lines as the console printed them. One run of that probe on each of the other consoles would settle it.</li><li>Why a store that misses the data cache takes three cycles longer on the console than on the emulator from each place it can begin at. One probe shows it; the bench's rows were tuned beside the shorter time.</li></ul></section>","20-rsp":"<section class=\"sect n64emu-chapter\" id=\"n64emu-20-rsp-sect\"><h3 class=\"sect-h\" id=\"n64emu-20-rsp\">The RSP</h3>\n<p>The RSP is a small processor inside the console's graphics and sound chip. Games load their own programs into it, mostly to work out the shapes of a scene and to mix sound, and it has a vector unit that does the same sum on eight numbers at once. The emulator runs those programs one instruction at a time, as the chip does, and knows nothing of what any of them is for.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-20-rsp--what-the-emulator-does\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-20-rsp-s1\">1. What the emulator does</h4>\n<ul class=\"gbemu-bullets\"><li>It runs the RSP beside the processor on the one clock. Before the processor reads or writes anything of the RSP's, the RSP is brought up to the same moment, so the two are never out of step by more than the one processor instruction that is running.</li><li>It keeps the RSP's two small memories and its eight registers as the console does, with the marks that say the RSP is halted, has stopped at a break, or is moving memory.</li><li>It moves blocks between main memory and the RSP's memories eight bytes at a time, in rows with a gap in main memory after each row, and counts the registers on while it does. A second move asked for while one runs waits for the first.</li><li>A move takes time, and how long depends on who asked for it. One that the RSP asks for itself is over sooner than one the processor asks for. When the RSP asks, a move of eight bytes is busy for 19 cycles into the RSP's memory and for 11 cycles out of it. These times are tuned to console measurements, and section 3 says how closely.</li><li>Every operation of the vector unit is worked out from its bits, with the running total of 48 bits and the three sets of flags the console keeps, and with the console's answer where a program lets a result overflow or divides by nothing.</li><li>The operations that have no name are emulated as well. Most of them add their two inputs into the running total and give back nothing. Six of them read an input that an earlier instruction has not finished writing, and get it as it was before.</li><li>It keeps the time of the RSP's pipeline: one cycle an instruction, a wait when an instruction reads what an earlier one is still writing, an empty cycle after a branch, and two instructions in one cycle where the console pairs them.</li><li>The vector unit exists twice: once in plain code, and once using the vector instructions of the browser. The second is the one that runs on the page, and the first is the reference it is held to.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> A game's program and the RSP hand work to each other through a few registers, and each waits on the other's answers. If one ran ahead, or a move of memory ended too early or too late, the order of those answers would not be the console's.</p></div>\n<span class=\"n64emu-alt\" id=\"n64emu-20-rsp--how-it-was-measured\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-20-rsp-s2\">2. How it was measured</h4>\n<ul class=\"gbemu-bullets\"><li><b>The system test suite</b>, recorded on hardware by its authors. Its tests of the RSP pass 227 of 227.</li><li><b>Test programs for the RSP that judge themselves on screen</b>, by another author. 54 of 54 give the verdict pass. One more is held to passing half of its cases and failing the other half, and section 3 says why.</li><li><b>Outputs of the vector unit recorded on hardware by their authors.</b> 1,380 of 1,380 come out the same.</li><li><b>A check of the pipeline's times</b> against the published rules, 37 of 37 cases. This holds the emulator to the rules as they are written, not to a console.</li><li><b>A sweep that holds the two vector units to each other.</b> Random instructions on random state go through both, and 300,000,000 of 300,000,000 cases come out the same.</li><li><b>The pair test of the vector unit</b>, by another author. It runs chosen pairs of inputs through the RSP and through a model of its own, and stops at the first difference. Its short form finds none in 32,768 cases. That is agreement between the emulator and another program's model, and no more than that.</li><li><b>Two probes written for this emulator.</b> The probe of the unnamed operations runs twelve of them straight after their inputs are loaded and prints 48 lines. The move probe has the RSP ask for 28 moves of memory and watch its own busy mark, and has the processor time what asking for a move costs it.</li><li><b>The bus timing bench</b>, by another author. It times sixteen moves that the processor asks for, by polling from the processor.</li></ul>\n<p>Each rule is also shown to fail once. A copy of the emulator is built with the rule wrong on purpose, and the check that guards the rule has to notice.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-20-rsp--what-two-pal-consoles-said\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-20-rsp-s3\">3. What two PAL consoles said</h4>\n<ul class=\"gbemu-bullets\"><li><b>The suite.</b> None of the 4,637 checks of the system test suite failed on either console, the RSP's among them. The emulator had the same result.</li><li><b>The unnamed operations.</b> Both consoles printed the same 48 lines, byte for byte. Before it was changed the emulator had 36 of the 48. The twelve it had wrong belong to the operations numbered 0x3C, 0x3D and 0x3E. Placed straight after the loads of their inputs, they read the inputs as they were before the loads. The emulator had made them wait for the loads, which is what the test suite expects of them and what a second emulator does. The suite passes on the same consoles all the same, because it loads the inputs in another order. The emulator now follows a rule that gives both results, and prints 48 of 48 of the consoles' lines.</li><li><b>The operation the suite calls VNULL.</b> One of the screen test programs expects it to clear part of the running total, and the suite expects it to change nothing. The consoles agree with the suite, as the emulator already did. So that screen program is held to passing 4 of its 8 cases and failing the rest. The program itself has not been run on a console.</li><li><b>How long a move takes when the RSP asks.</b> A move of eight bytes into the RSP's memory was still busy at cycle 15 and over by cycle 29. One out of it was over by cycle 15. The emulator had held the busy mark longer than that both ways, and was corrected. The printouts give a range for each move and not one cycle, and the two differ in 46 of their 386 lines: the same move does not always take the same time. The emulator's times now lie inside the consoles' range for 28 of 28 moves, and the check accepts nothing wider.</li><li><b>What asking costs the processor.</b> A read of the RSP's status straight after the processor asked for a move comes back one to three ticks of the processor's counter later than it does after a store that asks for nothing. A read of another chip's register is not held up at all. The emulator had no such wait. It now answers such a read 3 cycles later, a tuned figure, and the check holds what asking adds to within one tick of each console in 16 of 16 cases.</li><li><b>Moves the processor asks for.</b> The bus timing bench ran four times on the two consoles. Its shortest move reads 33 cycles in every run, and its long rows move by a few cycles from run to run. The emulator's times for these moves are tuned to the four runs. The bench run on the emulator lands inside the consoles' range, or less than a twentieth of a per cent outside it, on 2 of 16 rows, and within 10 per cent of it on 15 of 16. The short rows are the far ones: the bench polls, and a short move falls between two of its looks.</li><li><b>These consoles and the bench author's.</b> The bench's long rows are about 0.8 per cent longer on these two consoles than the figures its author lists for an NTSC console.</li></ul>\n<ul class=\"gbemu-bullets\"><li><b>A test that seemed to say the consoles' data cache differs.</b> One test of the vector unit copies its own program for the RSP into memory. On this emulator, and on another, a line of the processor's data cache is then written back over the start of that copy, and the test fails at once. On a PAL console the same test ran for an hour, about two dozen of its operations and some three million cases, with no difference. The consoles' cache is not the reason. That console run was listened to without the debug text window, and without a window the test's own library asks for no text buffer, so the copy lies lower in memory, where no line of the cache is in use. Run without the window the emulator runs the test whole too, and a probe that walks the same steps prints the same lines on the console as on the emulator. The processor's chapter has that measurement.</li></ul>\n<p>The RSP, its memories and the bus do not look at the television type, so everything above is expected to hold on an NTSC console. None has been measured, and the last point is the one place where an NTSC console is known to have given other figures.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-20-rsp--what-is-not-established\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-20-rsp-s4\">4. What is not established</h4>\n<ul class=\"gbemu-bullets\"><li>Whether the build of that test which the emulator's own check uses stops at once on a console listened to without the debug text window, as it does on the emulator without one. Nobody has watched it there. One watched run would settle it.</li><li>How that test should report to the computer that listens. Its lines reach the console's screen but not the flash cartridge's listener: the builds meant to send text the cartridge's way do not hold that routine. A build that does would settle whether the text then arrives. For now the test's record is a photograph of the screen.</li></ul>\n<ul class=\"gbemu-bullets\"><li>Which rule the consoles follow for the operations 0x3C to 0x3E. At least two rules fit everything measured. By the first, which the emulator has, these operations wait for their first input unless it is register 0. By the second they wait for it only when the instruction just before wrote it. A probe that loads the inputs in two more orders would settle it.</li><li>The cycle in which a move of memory ends. The consoles gave ranges 14 cycles wide, and other choices of times fit them as well as the emulator's. A probe that reads the busy mark once for each try, at a distance that is halved towards the answer, would give the cycle itself and show how far it moves from run to run.</li><li>Why a move the processor asks for takes longer than one the RSP asks for. Three things differ between the two measurements and were not separated: who asks, whether a picture is being shown, and whether the processor is polling. A probe in which the processor asks and the RSP watches, run with the picture on and with it off, would separate them.</li><li>Why the bench's long rows are longer on these consoles than on its author's. A run of the bench on an NTSC console would say whether the television type is the cause.</li><li>How a run of reads of the RSP's own registers is timed. On the consoles such reads do not come one a cycle, and on the emulator they do. A program that reads a clock from the RSP would settle it.</li><li>What holds the processor's read up after it has asked for a move. The emulator's wait is tuned and the cause is not known. The move probe run with every distance between the store and the read would show its shape.</li><li>Whether a console and the pair test's model agree. No console has run the pair test. A console run of it, left until it has been through every operation, would settle it.</li><li>Whether the screen test program that expects VNULL to clear the running total fails half of its cases on a console, as the probe's lines say it must. A console run of that program would settle it.</li><li>How long after the processor starts the RSP its first instruction runs. A test program that reads a clock around a start would settle it.</li><li>Most of the pipeline's times rest on the published rules. On a console only the time of a plain instruction has a test behind it. A program that times waits, branches and pairs through a clock the RSP can read would settle the rest.</li></ul></section>","30-rdp":"<section class=\"sect n64emu-chapter\" id=\"n64emu-30-rdp-sect\"><h3 class=\"sect-h\" id=\"n64emu-30-rdp\">The RDP</h3>\n<p>The RDP is the part of the console that draws. A program hands it a list of commands: set a colour, load a texture, draw a triangle or a rectangle. The RDP works the list off and writes the pixels into main memory, where the VI later reads them for the picture. Beside every byte of main memory the console keeps a ninth bit that a program cannot read in the usual way. The RDP keeps in those hidden bits how much of a pixel a shape covers, so this chapter is about them as well.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-30-rdp--what-the-emulator-does\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-30-rdp-s1\">1. What the emulator does</h4>\n<ul class=\"gbemu-bullets\"><li>It draws every pixel itself, on the processor of the computer it runs on, in the chip's own whole-number arithmetic. A triangle's edges are walked line by line, and each pixel passes the chip's stages: texture, colour combiner, blender, depth and coverage. The chip's four modes are built: one-cycle, two-cycle, copy and fill.</li><li>It keeps the hidden bits. The RDP writes a pixel's coverage into them and the VI reads them back to smooth the edges of shapes. Everything else that writes memory changes them too: a store by the processor, a line of its data cache written back, and a transfer by the PI, the SI or the RSP.</li><li>Drawing takes time. A command is charged the time two consoles took for it (section 3), and a triangle or a rectangle the time of its lines, by the mode and by each line's width. The busy marks in the RDP's status, its counters and the interrupt at the end of a list follow that time, and memory receives a shape's lines as their time passes, not all at once.</li></ul>\n<ul class=\"gbemu-bullets\"><li>It reads a list of commands into a buffer ahead of the drawing, as the console does (section 3): 80 bytes at a time, as long as the buffer has room. The place the RDP gives as its current one is the place of that reading, not of the command being drawn, and the marks in its status for the reading, for the buffer's room and for the buffer's work follow it.</li><li>A list of commands asked for while another is still being read waits its turn, whole, and begins when that reading is over. The RDP has room for one list in hand and one that waits; nothing of the one in hand is lost. Games rely on it every frame: their programs for the RSP write commands into a ring of memory and start again at its beginning while the RDP is still busy with its end.</li><li>A filled shape is written as the console writes it: eight bytes at a time, under a mask (section 3).</li><li>A program can stop the RDP where it stands, and it can have it take commands without drawing them. Both go as they went on a console (section 3).</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> A program can look at memory while the RDP is still drawing, and it can wait for the interrupt that says a list is done. If drawing took no time, such a program would find a finished picture where a console has drawn half of one.</p></div>\n<span class=\"n64emu-alt\" id=\"n64emu-30-rdp--how-it-was-measured\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-30-rdp-s2\">2. How it was measured</h4>\n<ul class=\"gbemu-bullets\"><li><b>Pictures a console drew.</b> A set of tests written by others keeps, for every picture its tests draw, the picture a console drew. The emulator draws 5,727 of 7,094 of them the same, byte for byte. The pictures that differ are of three kinds, and section 4 lists them.</li><li><b>A reference renderer.</b> A software renderer written by others to match consoles pixel for pixel draws the same scenes as the emulator, and 634 of 755 come out the same in every pixel. The other 121 differ only in two places where a better source than the renderer is followed. A second collection, lists of commands made by chance, is drawn by both as well, and 233 of 235 of its sets leave the same memory behind. A rule that rests on these alone agrees with another emulator, and no console stands behind it.</li><li><b>The open library's own tests.</b> An open library for the console carries a program of tests of itself. Of its tests that compare what the RDP and the VI did, the emulator passes 34 of 34.</li><li><b>A filled rectangle, as a console writes it.</b> One of those two places is a filled rectangle in a picture of 8 bits a pixel, where the renderer's own arithmetic goes another way than a console does (section 3). Two probes written for a console fill short runs of pixels and print the memory around them with its hidden bits. Run on the emulator, 296 of 296 cases of the first and 588 of 588 cases of the second are as the console's rule makes them, and every line the console printed is the emulator's line as well: 296 of 296 lines of the first probe and 2,912 of 2,912 lines of the second, in its three runs. Scenes made for the same rule, a picture beginning at each of four addresses and runs of pixels of every start and several lengths, come out byte for byte as the rule makes them: 8 of 8 scenes.</li><li><b>The list that waits.</b> Lists made for the test are handed over one straight after the other. A second list must wait whole while the first is being read, begin when that reading is over although the first is still being drawn, and wait for as long as the reading of a long first list stands still; every command of both must run: 62 of 62 facts. A game that lost 84 commands of one frame without the waiting list, and stopped, now goes on.</li><li><b>Probes of the reading, beside a console's lines.</b> Four probes written for a console read the RDP's current place and its status while lists run. Each is run on the emulator, and every value it prints is set beside the value the console printed. Where the reading stands while a large rectangle is drawn, the emulator has the console's place in 1,566 of 1,566 samples. Of the values the console printed for a second list handed over behind a first, the emulator has 56 of 66. On the way up, sampled every two thirds of a cycle, it has 499 of 512 samples for a list with a rectangle and 725 of 768 samples for a long list of settings. Section 4 says what the others are.</li><li><b>Two probes written for this emulator</b>, run on the emulator and on both consoles. The hidden bits probe stores into memory in every way a program can and reads the hidden bits back. The drawing time probe runs 24 lists of commands, each twice, and prints what the processor can see of the time each takes: the RDP's status, its counters and the moment of the interrupt.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-30-rdp--what-two-pal-consoles-said\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-30-rdp-s3\">3. What two PAL consoles said</h4>\n<p><b>The hidden bits.</b> The probe printed the same lines on both consoles, in three runs, and the emulator now prints 12 of 12 lines as they do.</p>\n<ul class=\"gbemu-bullets\"><li>The consoles corrected one rule. A word's first byte stored alone leaves zero in its hidden bit, whatever the byte is, where a word's second byte leaves its own lowest bit. The emulator had the first byte leave its lowest bit too, and 4 of the probe's 16 cases of a byte stored alone came out otherwise on the consoles.</li><li>The other rules were as the emulator had them: stores of 16, 32 and 64 bits, a line of the data cache written back, memory filled through the memory interface's repeat mode, and transfers by the PI, the SI and the RSP. Before these runs most of them were the natural reading of two known cases and nothing more.</li><li>The RDP's clock counter went 133,335 steps while the processor's counter went 100,002 on the first console and 100,001 on the second: four steps to the processor's three.</li><li>One line of the probe arrived without its first letter, on both consoles and in every run. Section 4 says what is known of that.</li></ul>\n<p><b>A filled rectangle.</b> Two probes asked one console what a fill writes into pictures of 8 and of 16 bits a pixel, in 820 cases over three runs. A fourth run asked the same of pictures of 32 bits a pixel, and of pictures of 16 bits that begin at an odd address: the same rule gave 64 of 64 cases.</p>\n<ul class=\"gbemu-bullets\"><li>The console does not fill pixel by pixel. It writes a line of a filled shape as whole words of eight bytes, each under a mask that says which of the eight bytes may change. How many words it writes is counted by where the line's bytes lie in the picture, in groups of eight, and not by their addresses in memory.</li><li>For a picture that begins on a multiple of eight bytes, as every game's does, that writes the line's own bytes and no other. For a picture that does not, a byte past the line can be written, the end of a line can be left out, and in 26 lines of the first probe the console wrote nothing at all.</li><li>Every byte written takes one bit of the fill colour as its hidden bit: the lowest bit of the half of the colour that the byte's address picks.</li><li>The emulator had filled pixel by pixel, by a hardware wiki's rule, and 44 of 296 lines of the first probe came out otherwise on the console. The rule above was found from the first two runs, and it then said beforehand what a third run would print for 180 cases no rule had been fitted to. All of them came out so, and every other rule tried failed where it had been expected to.</li></ul>\n<p><b>Reading a list.</b> Probes asked one console where the RDP's current place stands while a list is drawn, and how it gets there. Before these runs the emulator fetched each command when it ran it.</p>\n<ul class=\"gbemu-bullets\"><li>The console reads a list into a buffer, ahead of the drawing. While a rectangle of 320 by 200 pixels was drawn, in each of 87 lists, the current place stood still 200 to 256 bytes behind the rectangle's command: in the middle of a command, if that is where it fell.</li><li>The reading goes 80 bytes at a time, counted from the list's start, and takes a next block only while the buffer's bytes behind the command being drawn, and the block, are 256 or fewer. Commands that set something and shapes to be drawn wait in the same buffer, and nothing leaves it while a shape is drawn.</li><li>A block's ten words come in one cycle apart, and the next block 26 cycles after this one began.</li><li>A second list handed over while a first is still being read waits whole. The console showed both waiting marks for as long as the first list's reading stood still, and read and ran the second when the first list's rectangle was drawn. A second list handed over when the first has been read begins at once, while the first is still being drawn.</li><li>With the stop mark set while a rectangle of 200 rows was being drawn, the console stopped drawing where it was: 15 rows had been begun, nothing behind the rectangle ran, and no interrupt came until the mark was cleared. Then the list ran on whole.</li><li>With the mark that is said to end a list set for a short while instead, the console finished the row it was writing and drew no more of the rectangle. It went on reading and taking the commands behind it, and drew none of the 18 or 19 small rectangles it took while the mark was set. Those it took afterwards were drawn, and the interrupt at the list's end came. A hardware wiki says this mark ends the list; the console did not end it.</li></ul>\n<p><b>Drawing time.</b> Before these runs the emulator drew each command in no time, and the consoles corrected that. The figures are cycles of the clock the RDP runs on, from two runs of each list on each console. The rectangles are drawn into a picture of 32 bits a pixel.</p>\n<div class=\"gbemu-scroll\"><table class=\"gbemu-table\"><thead><tr><th>What</th><th>The consoles</th></tr></thead><tbody><tr><td>A command that sets a register</td><td>1 cycle</td></tr><tr><td>The three lesser syncs</td><td>50, 33 and 25 cycles</td></tr><tr><td>A rectangle of 320 by 64 pixels in one-cycle mode</td><td>37,045 to 37,120 cycles</td></tr><tr><td>The same in two-cycle mode</td><td>42,408 to 42,449 cycles</td></tr><tr><td>The same in fill mode</td><td>23,661 to 23,694 cycles</td></tr><tr><td>One more pixel in a line</td><td>about 1.8 cycles in one-cycle mode, 2.0 in two-cycle mode and 1.2 in fill mode</td></tr><tr><td>The pipe behind the last command</td><td>busy for 66 to 75 cycles more behind a list with nothing to draw, and longer behind a shape</td></tr></tbody></table></div>\n<ul class=\"gbemu-bullets\"><li>The interrupt comes when the pipe has run dry, not when the list is handed over, and no counter goes on after it.</li><li>Memory fills while a list runs. A rectangle 200 lines high was read four times on the way: at first none of three chosen lines was there, then the top one, and at the last look the middle one as well.</li><li>A line's time does not grow evenly with its width, and in one-cycle and fill mode a shape's first line is quicker than the lines after it. The emulator takes the consoles' times at widths of 8, 64 and 320 pixels and goes in a straight line between them.</li></ul>\n<p>In every value that is the RDP's own, the emulator lies within the range of the four console runs in 52 of 52 lines of the probe. Two values of a line also hold the processor's own time: how long its reads of the registers take, and where its waiting loop stands when the interrupt comes. In those, 40 of the 52 lines lie outside the consoles' range, each by less than one turn of that loop or one refresh of memory.</p>\n<p>None of these probes uses the picture or the sound, and the clocks they count are the same on every television type. So these results should hold on an NTSC console, but none has been measured.</p>\n<h5 class=\"gbemu-sub\" id=\"n64emu-30-rdp--a-load-from-a-4-bit-picture\">A load from a 4-bit picture</h5>\n<p>A game hands the RDP a picture to load into its texture memory and says how many bits each dot of it has. With 4 bits said, the two public renderers the emulator is held against refuse the command, and nothing written says what a console does. A test of our own gave such loads on a PAL console, measured on hardware in three runs, one for each kind of load, because the first such load of a run ends it. The console's RDP hangs. After a load of a rectangle or of a palette it answers nothing more, not even the command that asks it to say when it is done. After a load of one long line it still answers that command once, and hangs at the next list. The emulator had stopped drawing there and gone on answering; it now hangs as the console does, and every line the console printed is the emulator's line. Games do not meet this: the usual way to load 4-bit dots names the picture as 8-bit or 16-bit. It should hold on an NTSC console; none has been asked.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-30-rdp--what-is-not-established\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-30-rdp-s4\">4. What is not established</h4>\n<ul class=\"gbemu-bullets\"><li>What a load from a 4-bit picture leaves in texture memory before the RDP hangs. Nothing can be drawn from it afterwards, so a console cannot be asked this way.</li><li>At which command the RDP hangs after a load of one long line from a 4-bit picture. A test that follows that load with one command of each kind in turn would settle it.</li></ul>\n<ul class=\"gbemu-bullets\"><li><b>A colour changed with no sync before it.</b> On a console a fill colour set straight behind a rectangle is drawn with by the rows of that rectangle that are not written yet, and a sync before the colour stops that. The emulator takes every command in order, so no row takes a later colour. A probe timed every row of 202 lists on a console, to the cycle: rows of up to 64 bytes are read 9 cycles apart, a shape's last row later, and the times change with a row's length and with the blocks of memory it touches. No one rule tried gives all of them. A model of how a fill's words go to memory would; the probe's lines are kept as its test.</li><li><b>The reading under load.</b> In about one run in ten of the pace probe's later samples the console's reading lags a block or two behind its usual place, a short list behind a drawn one begins 8 cycles later than a long one, and a list begun while a rectangle is drawn is read more slowly. Memory's own turns are the likely cause; the emulator's reading is never held up. One mark of the status comes and goes on a console while a rectangle is drawn, about 7 cycles in every 16 to 18; the emulator keeps it set.</li><li>What a filled rectangle drawn in one-cycle or two-cycle mode writes into a picture that begins off a multiple of eight bytes. The console was asked about fill mode, in pictures of 8, 16 and 32 bits a pixel. The same probe with such a rectangle in place of the fill would settle it.</li></ul>\n<ul class=\"gbemu-bullets\"><li>Why one line of the hidden bits probe arrives without its first letter on both consoles. One explanation, that a read straight after the memory interface's repeat mode comes back wrong, has been tried on a console and ruled out.</li></ul>\n<ul class=\"gbemu-bullets\"><li><b>The lost letter.</b> The hidden bits probe's line for the repeat mode arrived without its first letter in every run. The probe switches the repeat mode on, stores one word, and in its next instruction reads a number it keeps in the data cache. The missing letter fits that one read giving a wrong value. Whether a read can go wrong straight behind such a store is not known. A probe that asks exactly this is written, and a console run of it would settle it.</li><li><b>Drawing time beyond what was measured.</b> The probe drew rectangles at three widths in three modes, and one triangle. Not measured: other widths, pictures of 16 and 8 bits a pixel, copy mode, texture loads, and drawing that reads memory first, as the depth test and blending with the picture do. The emulator charges these by rule of thumb. A second run of the probe with those cases would settle most of them.</li><li><b>Tuned constants of drawing time.</b> A triangle's line is charged a rectangle's of the same width and about three and a half cycles more, fitted to the one triangle measured. Lines reach memory eight at a time: the consoles show that memory fills on the way, not in what steps.</li><li><b>A row's time in a picture of 16 bits a pixel.</b> The probes of the reading also timed two things the drawing time probe did not draw. A row of 320 pixels of 16 bits takes the console about 186 cycles and the emulator 183.6, so a large rectangle ends a little sooner here. A rectangle of one row holds the commands behind it for 23 cycles when it is 19 pixels wide and for 30 when it is 64; the emulator charges 23.4 and 32.9.</li><li><b>Pictures of a console that the emulator does not draw.</b> They are of three kinds. In 1,131 pictures a triangle is drawn in fill mode with its long edge on the right. A console writes such lines in a way of its own, and its pictures gave the rule only in part. Games fill with rectangles, which no picture shows going wrong. In 20 pictures a colour is changed behind a fill-mode rectangle with no sync between, which is the reach named above. And 216 pictures show what drawing leaves in the chip's span buffers, which a test can read back; that is not built. Each needs its rule worked out from the pictures.</li><li><b>NTSC.</b> No NTSC console has been measured.</li></ul></section>","40-vi":"<section class=\"sect n64emu-chapter\" id=\"n64emu-40-vi-sect\"><h3 class=\"sect-h\" id=\"n64emu-40-vi\">The VI</h3>\n<p>The VI is the part of the console that sends the picture to the television. It counts the lines of the picture against a video clock of its own, raises an interrupt at a line the program chooses, and for every line reads pixels from main memory, passes them through its filters and puts them out.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-40-vi--what-the-emulator-does\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-40-vi-s1\">1. What the emulator does</h4>\n<ul class=\"gbemu-bullets\"><li>It counts in half-lines, as the chip does, as a PAL, an NTSC or an MPAL console: each has its own video clock and its own number of lines, with interlace and without.</li><li>It raises the interrupt on the step that brings the counter to the half-line the program chose, whether that step is a line's start or its middle. While the VI is off the counter stands still and no interrupt comes.</li><li>It makes the picture a line at a time, from the registers and the memory of the moment the line starts. A change in memory, or in the picture's address or scale, in the middle of a field shows on the lines after it and on none before.</li><li>It builds the chip's filters: the smoothing of partly covered pixels, which reads the hidden bits the RDP left in memory, the filter that takes dither out, the colours between the pixels of a stretched picture, gamma and its dither.</li><li>As a PAL console it does what two consoles showed when the VI is turned off and on (section 3).</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> Programs time themselves by the line counter and its interrupt, and some change the picture in the middle of a field. A picture made once a field from one look at memory would be wrong for those.</p></div>\n<span class=\"n64emu-alt\" id=\"n64emu-40-vi--how-it-was-measured\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-40-vi-s2\">2. How it was measured</h4>\n<ul class=\"gbemu-bullets\"><li><b>The registers, the line counter and the interrupt</b> are held, case by case, to what a public hardware document reports from consoles. The emulator passes 30 of 30 checks.</li><li><b>The picture</b> is compared with a reference renderer written by others to match consoles, and 3,872 of 3,872 pictures are the same in every pixel. They come from test programs written by others and from pictures made for the purpose, so that every setting of the filters is covered. This agrees with another emulator: no picture has been captured from a console.</li><li><b>The picture over time</b>, what a change in the middle of a field does, passes 8 of 8 checks.</li><li><b>The VI probe</b>, written for this emulator, prints 229 lines about the registers, the line counter and the interrupt. It was run on the emulator and once on each console.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-40-vi--what-two-pal-consoles-said\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-40-vi-s3\">3. What two PAL consoles said</h4>\n<p>Against the second console's printout the emulator, run as a PAL console, now has 81 lines the same, 78 lines the same but for times within a fiftieth, and 70 lines different, of 229.</p>\n<ul class=\"gbemu-bullets\"><li><b>As the emulator had it:</b> what the registers hold when a program starts, which of their bits can be written, how long a line lasts, what the counter reads across the end of a field with interlace and without, and that no interrupt comes with the VI off or with its line set beyond the field.</li><li><b>Corrected by the consoles: turned off, the counter still shows where it stood.</b> Read straight after the VI was turned off it gave the half-line it had reached, on both consoles, and zero a little later. The emulator gave zero at once. It now holds the value for one line's time, a time the consoles only bound.</li><li><b>Corrected by the consoles: turned on, the counter first moves late.</b> Its first step came 3,057 steps of the processor's counter after the write, on both consoles, where a line lasts 3,000 and the emulator had 3,013. The emulator's first line after the VI was turned on was then made 44 steps longer, a figure tuned through that test's own loop of reads. A second test, made to time the first interrupt to one cycle of the processor, showed on a console that this was too long: the emulator's first line is now 20 steps longer, and the interrupt's line then shows at the same moment as on the console in 9 of 9 trials. Why a console does this is not known.</li><li><b>The interrupt comes with the counter's step</b>, as in the emulator: the counter reads the same at every interrupt of the probe's eight cases. In 6 of those 8 lines the printouts still differ in which of two looks the probe's loop makes first, and by how many steps. That is the time the processor's reads take, which belongs to the chapter on the processor.</li><li><b>The 64 other lines that differ</b> are about how the picture slows the processor's reads of memory. They belong to the processor's timing as well.</li></ul>\n<p>The two corrections are built for a PAL console only. As an NTSC or an MPAL console the emulator is as it was, and nothing here is claimed for those types: none has been measured.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-40-vi--what-is-not-established\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-40-vi-s4\">4. What is not established</h4>\n<ul class=\"gbemu-bullets\"><li><b>The picture on a console.</b> No picture has been captured from a console's video output, so everything about the filters agrees with another emulator and no more. A capture of a known picture from a console would settle it.</li><li><b>How long the counter keeps its value after the VI is turned off, and why its first line is late.</b> The probe read the counter twice. Reading it in a loop would give the time. Whether an NTSC console does the same is not known.</li><li><b>One late interrupt.</b> With the interrupt set to half-line 14 and no interlace, the first interrupt came 54 steps after the counter was seen to change, on both consoles, and the three after it came with the change. This is not explained.</li><li><b>Inside a line.</b> A console fetches a line's pixels as it sends them, so a write during a line can show on the rest of that line. The emulator takes the whole line as memory was at its start.</li><li><b>What can hang a console's VI.</b> A public hardware document names three things a program can do that are said to hang or harm a console. The emulator goes on as if nothing had happened and keeps a note of each.</li><li><b>NTSC and MPAL.</b> Nothing has been measured on such a console.</li></ul></section>","50-ai":"<section class=\"sect n64emu-chapter\" id=\"n64emu-50-ai-sect\"><h3 class=\"sect-h\" id=\"n64emu-50-ai\">The AI and the sound check</h3>\n<p>The AI is the console's sound output. A program leaves finished sound in main memory, 16 bits for the left side and 16 for the right, and tells the AI where it is and how long it is. The AI takes it from memory a little at a time and hands it to the console's converter chip, at a rate the program sets. It changes nothing in the sound.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-50-ai--what-the-emulator-does\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-50-ai-s1\">1. What the emulator does</h4>\n<ul class=\"gbemu-bullets\"><li>It holds two transfers at most: one playing and one waiting. A length written while nothing plays starts a transfer at once and raises the AI's interrupt. A second length waits behind the first. A third takes the waiting one's place.</li><li>It fetches sound from memory eight bytes at a time, which is two frames, and keeps one such piece ahead of the one it is playing. A transfer started from rest fetches its first piece a moment after it is written, 21 video-clock cycles on, and its second 14 cycles after that; then one piece is fetched every two sample periods.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> The console's own length register falls in these steps and at these moments.</p></div>\n<ul class=\"gbemu-bullets\"><li>A transfer is over, and its busy mark falls, when its last piece is fetched. The frames already fetched still go out.</li><li>The sample period is counted in cycles of the video clock: twice half the rate setting, rounded down, plus one. That is the setting plus one when it is odd, and plus two when it is even.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> The clock is a counter that runs down from half the setting twice in each period.</p></div>\n<ul class=\"gbemu-bullets\"><li>The sample clock stands while the second rate register is zero, which it is when the console is switched on. It starts when a program first sets that register, 9 video-clock cycles after the write, and it starts afresh every time the register comes back from zero. A fresh start begins with a whole half period, and the word clock, which says whether the left or the right half of a frame is leaving, goes on as it stood.</li><li>Each frame is taken for its sample period a little before the period begins: when the last bit of the frame before has left, at the pace of the bit clock that the second rate register sets. With the settings a program uses that is 26 video-clock cycles before the period begins, and that is the moment at which the next piece is fetched.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> On the console a quicker bit clock makes every fetch come sooner, and the counter the console shows stands where this gives it.</p></div>\n<ul class=\"gbemu-bullets\"><li>The video clock is another for each television type, so one setting gives three pitches. The period is never rounded to the emulator's own clock, so a long sound neither gains nor loses.</li><li>The second rate register sets the converter's bit clock. While it is zero the sound chip holds no transfer. One written then is over at once: its interrupt comes, its length reads nothing, and none of it is played. One that is playing when zero is written is cut on that write, and a second one waiting behind it goes with it.</li><li>A cut with a transfer waiting raises the interrupt a moment later, 8 video-clock cycles after the write. A cut of one transfer alone raises none.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> That is what the console showed. Why the interrupt comes only with a transfer waiting is not established.</p></div>\n<ul class=\"gbemu-bullets\"><li>What the chip had already fetched when it was cut stays where it is while the register is zero. It goes out once the register is written again, and the next transfer follows it.</li><li>It hands the browser the frames as they stand in memory, with their exact rate, and silence when nothing plays. While the sample clock stands it hands over nothing. It adds nothing and filters nothing.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> An emulator's own way of bringing frames to a sound card's rate can add sound that the frames do not hold; the next section measures one that does. The decision for this emulator, taken on hearing both, is to play the console's own frames.</p></div>\n<span class=\"n64emu-alt\" id=\"n64emu-50-ai--how-it-was-measured\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-50-ai-s2\">2. How it was measured</h4>\n<ul class=\"gbemu-bullets\"><li>The register tests write the AI's registers as a program would and let exact amounts of time pass. 45 of 45 pass, each to the tick, and 30 of 30 copies of the emulator made wrong on purpose are caught by the tests written for them.</li><li>The sound register probe is a small program of ours that plays silence in a dozen ways and prints what the registers read. The tone probe plays a square wave and times it with the processor's own clock.</li><li>The sound cut probe writes zero to the second rate register while silence plays, with one transfer and with two, and prints what the registers read and how long the next transfer then takes. In its later lines it reads the sample clock's own counter around such a write, starts the clock afresh at chosen places of a sample period, sets other bit clocks, and reads the length at counted moments after a transfer is written.</li><li>The sound check plays a known tune of 58 notes through the whole machine and reads the result by counting: every frame, every note's pitch and height, the rate and the length. As an NTSC console 14 of 14 measures come out as stated beforehand, and as a PAL console 6 of 6 against the tune alone.</li><li>Another emulator plays the same tune as a second opinion. Its AI is handed the same frames: 458,752 of 458,752 are equal.</li><li>That emulator's output is not those frames. It carries them to 48,000 samples a second by a rule of its own, and the rule adds two faint tones for every note. Carried by that same rule our frames are its output exactly: 0 of 899,050 values differ. Against the frames carried cleanly, what its rule adds stands 43 dB under the music on the left and 48 dB on the right. A listener heard that difference side by side, as a hum under the music, before it was measured.</li><li>The clean way of carrying frames used for that comparison leaves a residue 131 dB or more under the music below 20 kHz.</li><li>Run as a PAL console, the emulator's sound rate is the video clock over the sample period.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-50-ai--what-two-pal-consoles-said\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-50-ai-s3\">3. What two PAL consoles said</h4>\n<ul class=\"gbemu-bullets\"><li>The sound register probe ran three times on one console, each time with more lines. Run as a PAL console, the emulator now gives 45 of 45 of its lines. Before it was changed it did not: the next three points list what the console corrected.</li><li>The console corrected four rules. A third length takes the waiting one's place; the emulator used to drop it, as some emulators do. The second rate register at zero does not hold a transfer back. Even rate settings last longer than was thought: the settings 1104, 2208 and 258 gave periods of 1106, 2210 and 260 cycles, not one more than the setting. And sound is fetched ahead: the emulator used to fetch each piece only as it was needed.</li><li>The second run corrected one rule more. With the second rate register at zero a transfer was over at the probe's first look, 46 counts of the processor's counter after it was written. The emulator had played such a transfer out at its usual pace, as other emulators do. It now ends it at once, as the console does.</li><li>The third run corrected one rule more. A transfer that was playing when the second rate register went to zero was gone at the next read: its length read nothing where 1,952 bytes had been left a moment before, and it did not come back when the register was set again. The emulator had let such a transfer play on, as other emulators do. It now cuts it.</li><li>The sound cut probe then asked what goes with a cut, each case three times. With a second transfer waiting, both were gone at once and the interrupt was raised; with one transfer alone it was not. A transfer written straight after the cut ended 62.96 to 63.43 sample periods after it was written, where the same transfer from rest takes 59 to 60 on the emulator: it had to wait behind what the chip had fetched before the cut. Run as a PAL console, the emulator gives 18 of 18 of that run's lines.</li><li>The cut probe ran three times more with further lines, and the runs agree. They showed that the interrupt of a cut comes a moment after the write and not with it, that what the chip had fetched stays in place however long the register is zero, and that the chip's own counter starts afresh when the register is written again: at the first look after such a write it read 548 or 549 of its 551 every time. The emulator has all three.</li><li>The probe then ran twice with lines written to ask where the clock starts and what paces a fetch, and the two runs agree. A transfer written straight after a fresh start ended half a sample period later where the word clock had stood high than where it had stood low. The same transfer ended sooner the quicker the bit clock was set, 32 video-clock cycles for each cycle the bit clock's turn was shorter. And a transfer's length read whole at a look made straight after it was written, in 198 lines of 198: its first fetch comes a moment later. The emulator had started its clock at the first write of the first rate register and let it run on through zero, had made every fetch at the start of a sample period, and had made a transfer's first fetch with its write. It now does as the console did. Run as a PAL console it gives 609 of 609 lines of the probe's six runs, a time counting as given when it is one the console showed for that line to within one turn of the probe's waiting loop.</li><li>The tone probe ran on both consoles. They played the rate setting 1103 at 26 parts in a million and 14 parts in a million above the rate the emulator's rule gives, which is well within what a console's two crystals may differ by.</li><li>The other emulator, run as a PAL console, plays 166 parts in a million fast, because it rounds the sample period to its own clock. The consoles contradict that.</li><li>Should this hold on an NTSC console? The AI's logic is the same in every console and only the crystal differs, so the rules are expected to hold and the rates to follow the NTSC crystal. No NTSC console has been measured.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-50-ai--what-is-not-established\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-50-ai-s4\">4. What is not established</h4>\n<ul class=\"gbemu-bullets\"><li>What comes out of the sound chip when a transfer is cut and while its second rate register is zero. The registers do not show it. The emulator sends nothing while the register is zero, and sends what it had fetched before a cut once the register is written again. A recording of a console would settle it.</li><li>Why a cut raises the interrupt only when a transfer waits. The console showed that it does; no line shows the cause.</li><li>What turns the word clock. In most of the console's lines it turns where the counter runs out, and the emulator has it so. In a few lines of the probe's last two runs it had turned some tens of cycles sooner, after other bit clocks and another rate had been set, and the transfers of those lines followed the word clock as it read. Lines that read the counter at counted moments after a fresh start would settle it.</li><li>What a new setting of the first rate register does while the clock runs. On the console the counter took it when it next ran out, and the word clock then turned at the middle of the counter's run. The emulator lets it take hold at the start of the next sample period. A line that times a transfer after such a write would settle what the fetches then follow.</li><li>Why a transfer's first fetch came later than usual three times in some 300 on the console. Main memory is refreshed once in each line of the picture and takes no request meanwhile; a fetch that met the refresh would wait so. Lines that start transfers at counted places of a picture line would settle it.</li><li>Where the sound itself lies against the fetches. The emulator sends a transfer's first frame in the first sample period to begin after its first piece has been fetched and has moved up. A recording of a console would settle it.</li><li>What the console's converter chip and the analogue parts after it add to the frames. A recording of a console playing the tune would settle it.</li><li>What the converter is fed while nothing plays. A recording of the level probe would settle it.</li><li>Whether any of this differs on an NTSC or an MPAL console. The same probes on such a console would settle it.</li></ul></section>","60-pi":"<section class=\"sect n64emu-chapter\" id=\"n64emu-60-pi-sect\"><h3 class=\"sect-h\" id=\"n64emu-60-pi\">The PI</h3>\n<p>The PI is the part that talks to the cartridge. The processor reads the cartridge through it a word at a time, and asks it to copy whole blocks into main memory while the program runs on.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-60-pi--what-the-emulator-does\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-60-pi-s1\">1. What the emulator does</h4>\n<ul class=\"gbemu-bullets\"><li>A read of the cartridge by the processor waits for the bus. How long depends on the speed registers of the part of the bus that is addressed, and the bus has two such parts, one for the game and one for save memory.</li><li>When a program starts, the save memory part of the bus is at its slowest setting, and sends the address again for every four bytes. A program that uses save memory sets its own speed first.</li><li>A write by the processor is taken by the PI and done in the background. While it is in hand a mark shows in the PI's status, and a read of the bus gives the word that was written.</li><li>A block copy takes time. The bytes are in memory, and the PI raises its interrupt, only when the copy has ended, and the program runs on in between.</li><li>A block copy that starts at an odd address or has an odd length follows the PI's own rules for where it begins in memory, where the two address registers stand afterwards and what the length register then reads.</li><li>A copy out of memory takes its bytes from memory eight at a time. A short copy that starts a few bytes past such a group of eight does not take the last group it would need. The bytes it lacks are not memory's: the cartridge is sent what the PI's buffer held from the copy before.</li><li>A copy out of memory takes longer than the same copy into memory. Each block of 128 bytes after the first costs the time the address is held on the bus and 25 cycles more, unless it begins a page of the bus. A game feels it when it writes its save memory.</li><li>A second request made while the PI is busy is refused.</li><li>A game file is taken in any of the three byte orders such files are found in.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> Games start a copy and go on working. A copy that is done at once gives a program its data before a console would, and hides every fault that depends on the wait.</p></div>\n<span class=\"n64emu-alt\" id=\"n64emu-60-pi--how-it-was-measured\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-60-pi-s2\">2. How it was measured</h4>\n<ul class=\"gbemu-bullets\"><li>A check drives the PI's registers one rule at a time. 38 of 38 rules hold.</li><li>A test set, recorded on hardware by its authors, holds block copies of many shapes with the registers each one left and the time it took. The emulator gives 24,512 of 24,512 of those copies the recorded registers, and each takes the recorded time, give or take a tenth.</li><li>The same test set's own program judges the copies as it runs. It reports success in 64 of 64 rows.</li><li>A probe written for this emulator asks about a copy out to save memory, a second request during a copy and timed transfers. On the emulator 88 values are held to what is expected of them.</li><li>A second probe asks the odd cases over again as a table. It ran on the console, and the emulator gives 159 of 159 lines that are held to the console's printout. The emulator's own printout of it is kept as well, 258 lines, so that a change to the emulator shows.</li><li>The moment a copy starts was tried at 21 settings on four instruments at once: the probe, the recorded test set, a bus timing bench and a probe of save memory.</li><li>The helper that turns a game file's byte order is held by 30 of 30 checks.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-60-pi--what-two-pal-consoles-said\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-60-pi-s3\">3. What two PAL consoles said</h4>\n<ul class=\"gbemu-bullets\"><li>A bus timing bench ran on both consoles. Its rows for the game's part of the bus read as the bench's own table has them: a word read by the processor took 144 cycles on both, and a copy of 128 bytes took 1,591 cycles. The emulator's times were tuned to that table before the consoles were tried, and the consoles gave the table again.</li><li>The two rows for the save memory part of the bus read 70 and 68 cycles, where the bench's table has 808 and 800. The bench sets the speed of that part itself before it measures, so those rows do not show what a program finds there.</li><li>What a program finds there was read by the probes themselves, on every run that prints it: the slowest speed, with the address sent again every 4 bytes. The emulator had the slowest speed and the longest stretch between addresses. It now starts as the console does. With that setting a copy of 16 bytes from save memory took the console 2,411 to 2,512 counts of the processor's counter, and the emulator's falls in the same range.</li><li>The probe of the PI ran twice on the first console. Before the emulator was changed, its printout was the console's in 16 of 30 lines. Now it is in more, 17 or 18 of 30 lines, and each of the others is listed with its reason.</li><li>A copy of 16 bytes out of memory that began two bytes past a group of eight delivered 14 bytes on the console. A copy of 300 bytes from the same place arrived whole. The emulator had sent all 16. One rule gives both results, and the emulator now follows it: the PI takes the groups of eight that the length calls for, counted as if the copy began on a group.</li><li>The second probe then asked the same of many more copies. All 156 short and odd copies out of memory put on the bus what the emulator puts there, the bytes sent in place of those not taken among them. The emulator's rule had been written from the one case; the console gave the other 155 as well.</li><li>The same run timed copies of seven lengths both ways. Out of memory, a copy of 512 bytes took 203 to 206 counts longer than the same copy into memory, and a copy of 128 bytes or less took the same time, give or take one turn of the probe's waiting loop. A further run at other speed settings showed the extra time following the time the address is held on the bus, and not the length of the strobe. The emulator had given both directions one time. It now gives a copy out of memory the extra time, and its times out of memory less its times into memory are the console's in 28 of 28 lines, each within one turn of the probe's waiting loop.</li><li>The speed registers do what they are said to do. A longer strobe made a copy of 256 bytes take 1,728 counts longer on the console and on the emulator alike.</li><li>A copy begins 11 cycles after the request. The figure is tuned: a tool builds the emulator with each figure in turn and runs the instruments that ran on our consoles on every build. The emulator had 23 before, tuned before the processor's bus times were measured on a console, and a copy into memory then ended later on it than on the console: in nine of the probe's twelve timed lines by 9 to 14 counts. With 11, 7 of 12 of those lines lie inside the console's range and the rest within one turn of the probe's waiting loop. A copy that begins sooner moves every program against the lines of the picture, so the printouts kept for other parts were taken again with it.</li><li>A later build of the odd cases probe looked at a short copy into memory 255 times at each moment near its end, and ran twice. The end itself stands still: at one moment half the looks find the PI busy, and after it few do. But about one copy in 25 ends late, by up to some hundred processor cycles, and it does so with the picture switched off as well as on; a picture adds a few more. The emulator's copy ends at the one moment every time, some 20 processor cycles after the console's.</li><li>The same build reset the PI in the middle of a copy and read the bus address register at counted moments after. The register shows where the copy had got to for a moment more, and then a word of its own that holds what was left of the length. It changes with time and not with the reads. The emulator goes on showing where the copy had got to.</li></ul>\n<p>The PI does not look at the television type, so these results are expected to hold on an NTSC console. None has been measured.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-60-pi--what-is-not-established\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-60-pi-s4\">4. What is not established</h4>\n<ul class=\"gbemu-bullets\"><li>When a copy really starts. The three waiting loops disagree by about ten cycles, which points at what a turn of each loop costs the processor and not at the PI. The second probe measured it with no loop at all: it waits a counted number of single steps and looks once. Its looks moved from run to run, and, made sixteen times over, from try to try. The earliest lie a few processor cycles before the emulator's, and many found the copy still running later than that, which is not explained. The same looks with the picture switched off would show whether something else on the console holds a copy up.</li><li>When a copy begins. The emulator's figure is the one tuned before the processor's bus times were measured, and the instruments now ask for a sooner one. Moving it, with every kept printout taken again, would settle it.</li><li>What holds up the one copy in 25 that ends late. Main memory is refreshed once in each line of the picture, and that is the candidate. Lines that note where in a picture line each late end fell would settle it.</li><li>What the bus address register shows after a reset in the middle of a copy of another length or start, and at which moments of a copy its own word is there at once. One shape of copy was reset. A reset at every moment of one block, and of copies of other shapes, would settle it.</li><li>What the PI does in the extra time of a copy out of memory. The console shows the extra time growing with each block of 128 bytes after the first and following the time the address is held on the bus, which is what sending the address again for every block would cost. The emulator charges that time and does not say what is sent. A look at the bus itself would show it.</li><li>What the PI's cartridge address register holds after the PI is reset in the middle of a copy. In the second probe's first run the console read a fixed mark and what was left of the copy's length 2 of 3 times, and once a place inside the block being fetched. Further runs with more resets gave the same two kinds of word, and showed the register still changing in the moments after a reset. What it settles to, and when, is not shown. The emulator keeps the address the copy had reached.</li><li>Whether the flash cartridge's start-up program, which ran first in every run so far, really leaves the save memory part of the bus alone, as its own source says. A run started by the console's own firmware would confirm it. The boot firmware does leave it alone: run on the emulator, it writes the game's part of the bus and not the other, in 3 of 3 firmware files, so the setting a program finds is the PI's own.</li><li>The time of a copy at speed settings no test uses.</li><li>A disk drive on the bus. None is emulated.</li></ul></section>","70-si-pif":"<section class=\"sect n64emu-chapter\" id=\"n64emu-70-si-pif-sect\"><h3 class=\"sect-h\" id=\"n64emu-70-si-pif\">The SI and the PIF</h3>\n<p>The PIF is a small chip of its own inside the console. It holds the boot firmware, checks the cartridge's lockout chip, and talks to the controllers and to the save chip some cartridges carry. The SI is the link between it and the rest of the machine.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-70-si-pif--what-the-emulator-does\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-70-si-pif-s1\">1. What the emulator does</h4>\n<ul class=\"gbemu-bullets\"><li>The PIF has 64 bytes of memory. A program writes a list of requests there, one for each controller port and one for the cartridge, and reads the answers back the same way.</li><li>Every transfer takes time, 4 bytes or 64, and the PIF answers a request only when it is free. After each request it stays busy a while longer, so a request asked straight after another waits, and the same request after a pause is quicker.</li><li>A controller answers with its buttons and its stick. A port with nothing in it does not answer, and the PIF waits a fixed time before it gives up.</li><li>A controller sends its answer by its own clock. The console maker's own controller keeps close to the PIF's pace.</li><li>A Controller Pak and a Rumble Pak in a controller, and an EEPROM in the cartridge, answer on the same wires.</li><li>A controller says whether a pak is in it. With nothing in it since the console was switched on it says so with one value, and a read or a write of the missing pak is answered as if all were well. After a pak is pulled out with the power on it says so with another value, and a read comes back with its check code turned over. A pak pushed in is reported once as newly put in.</li><li>A pak is read and written at an address that carries a check of its own. A request whose check is wrong is answered with empty bytes and the check code turned over, and the controller's next word about itself carries an error mark, once.</li><li>The boot firmware and the PIF hand a program a few registers at start. One of them carries a mark that the PIF sets in an NTSC console and does not set in a PAL one.</li><li>The SI's registers repeat every 32 bytes. Its two address registers for the PIF both read the place of the last transfer of either size.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> A game reads its controllers once a picture and waits for the answer. An answer that comes at once, or comes at the wrong moment, changes what the game sees on the same picture.</p></div>\n<span class=\"n64emu-alt\" id=\"n64emu-70-si-pif--how-it-was-measured\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-70-si-pif-s2\">2. How it was measured</h4>\n<ul class=\"gbemu-bullets\"><li>A check drives the SI and the PIF one rule at a time. 42 of 42 rules hold.</li><li>A console bench lists how long 39 kinds of transfer take. The emulator's times are tuned to that table, and 39 of 39 rows come out within three parts in a hundred of it.</li><li>Seven test programs written by others judge controllers, paks and the EEPROM by themselves. 25 of 25 tests in them pass.</li><li>A probe written for this emulator prints the PIF's memory, the SI's registers, what each port answers and seventeen times. The lines consoles printed are kept beside it for three ways of plugging things in, and the emulator, run as those consoles were, gives every line that is demanded of it. With nothing plugged in that is 61 of 61 lines. With the maker's own controller and a Controller Pak it is 60 of 60 lines, and with that controller and nothing in it 60 of 60 lines. Of the seventeen times with nothing plugged in, 10 lie inside the range the consoles gave, and with the controller 13.</li><li>A second probe asks a controller about its pak. It reads, and its one write is sent only when the controller has just said that no pak is in. It ran on a console with the maker's controller, with a Controller Pak in it and with nothing in it, and the emulator, run as that console was, gives 20 of 20 lines and 23 of 23 lines. The emulator's own printout of it is kept as well, 150 lines in six ways of plugging things in, so that a change to the emulator shows.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-70-si-pif--what-two-pal-consoles-said\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-70-si-pif-s3\">3. What two PAL consoles said</h4>\n<p>The probe ran on both consoles with nothing in the controller ports: once started the usual way, through the flash cartridge's own start-up program, and twice started by the console's own boot firmware. It then ran five times on the first console with one controller plugged in, once with a Rumble Pak in it and four times with a Controller Pak. That controller turned out to be a third-party one. The maker's own controller was then run seventeen times with the two probes: with a Controller Pak in it, with a Rumble Pak pulled out and pushed back by hand, and with nothing in it.</p>\n<ul class=\"gbemu-bullets\"><li>Before the consoles were tried, the emulator's printout differed from the first console's in 9 of 46 lines.</li><li>Started by its own firmware, each console handed the program 6 in the register that carries the PIF's mark. The emulator had handed over 7, with the mark set, in agreement with another emulator. A PAL console's PIF does not set the mark, and the emulator now does as the consoles do. This is a PAL result: an NTSC console's PIF is said to set the mark, and none has been measured.</li><li>The consoles corrected the SI's registers. They repeat every 32 bytes and not every 64. The memory address register keeps whole words, and after 64 bytes it stands at the last eight of them. A word asked for through the SI's own data register is already there when the register is read next.</li><li>A mark that the PIF sets while the firmware runs is gone by the time a program starts. The emulator had left it standing.</li><li>A word read from the PIF after a pause took 982 to 1,005 counts of the processor's counter. The bench's figure for the same read, one straight after another, is half as long again, and the bench gave that figure on these consoles too. Both are right: the PIF stays busy after each request. The emulator now has that pause, tuned to these printouts.</li><li>The times moved by a few counts from run to run and between the consoles. The probe measures with a loop that takes 14 counts a turn on the emulator, so the check accepts a time within one turn of the range the consoles gave. Three times lie further out, the furthest by 40 counts, and the check says so for each.</li><li>The probe's times hang on the processor's own bus times too: it reads the counter between two stores and asks in a loop behind a third. Those bus times are now measured on a console directly. With the maker's controller plugged in, two long times stand furthest out: the read of four controllers with one plugged in, and the read on the cartridge's channel. The check allows them 154 counts and 518 counts, the emulator's own distance in whole turns of the loop. Nothing in the emulator's model of the controller ports is tuned to either: on the consoles the cartridge's channel was answered by the flash cartridge, in its own time.</li><li>The third-party controller's runs had corrected three rules the emulator had from a document, and the maker's controller took two of the corrections back. Both controllers say at their first answer that a pak is simply there when it was there from the start. But the third-party one gave no answer at all to a read with a wrong address check and left no error mark, and the emulator was made to do so; the maker's controller answers such a read with empty bytes and the check code turned over, in all 78 cases, and its next word about itself carries the error mark. The mark goes when the controller is asked about itself again, or when a good read follows. The emulator now does as the maker's controller does, and the other controller's lines are kept as a record of another kind of controller.</li><li>With nothing in its slot since the console was switched on, the maker's controller gave a value the documents give to a controller that cannot take a pak at all, where the emulator had said that a pak was taken out. Every read of the missing pak was answered with empty bytes and the check code that fits them, and so was a write, in 6 runs of 6, where the documents and the emulator had the code turned over as a sign that no pak is there. The third-party controller had said the same.</li><li>A Rumble Pak was pulled out and pushed back by hand while the second probe watched. Pulled, the controller said that a pak was taken out and a read came back with its check code turned over. Pushed back, it said once that a pak was newly put in, and at the next asking that one was there. That is what the documents say, and what the emulator does.</li><li>A reply of 33 bytes from the maker's controller took 48,329 to 48,343 counts longer than a reply of 3, which is the PIF's own pace to a thousandth. The third-party controller's took some 480 counts more. The emulator has the maker's controller's time.</li></ul>\n<p>Apart from the mark, the SI and the PIF are not known to look at the television type. Whether an NTSC console's PIF keeps the same times has not been measured.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-70-si-pif--what-is-not-established\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-70-si-pif-s4\">4. What is not established</h4>\n<ul class=\"gbemu-bullets\"><li>Why a Controller Pak read past its end gave bytes that changed from run to run with the third-party controller, and empty bytes every time with the maker's. Two paks were used, one with each controller. The same pak read through both would settle whether it is the pak or the controller.</li><li>Whether a read made after a pak is pushed in, and before the controller has been asked about itself, is refused. A document says so, and the emulator does it. The one run that shows a refused read then cannot tell it from a read made a moment before the push. The watch with its two requests the other way round would settle it.</li><li>What a write to a pak with a wrong address check does, and what a write answers after a pak is pulled out. The emulator treats a write as the console showed a read is treated. The probes never write to a pak that is in, because the paks hold saved games.</li><li>Why every time of the second probe is some 110 to 160 counts shorter in a few runs. It was so in the first run made after a new build of the probe was sent to the flash cartridge, twice, and not in the run after. A run after the cartridge's own power was cut would show whether the cartridge's stand-in for the lockout chip is the cause.</li><li>Why the read of all four controllers at once, with one plugged in, takes longer on the console than on the emulator, by 153 counts, when the same controller read alone agrees. The difference is one bit's time on the wire, and it was there with both controllers. Requests for two and for three ports would show where the bit belongs.</li><li>The mark in an NTSC and in an MPAL console. For MPAL two sources disagree, and the emulator has a setting for it. A console of each type, started by its own firmware, would settle it.</li><li>What the flash cartridge's start-up program does to the PIF before a test runs. After the usual start the PIF left the probe's own end-of-boot request standing, and after a start by the console's firmware it took it. A probe line that prints the PIF's state before anything is written would say more.</li><li>How the two fields of the SI's status that show its inner state change during a transfer. The consoles gave one value right after each request, 7 on some runs and 8 on others in one field.</li><li>Why three of the seventeen times with nothing plugged in stand further from the consoles than one turn of the loop. One is the read of four controllers, where the bench's own row on the same consoles is longer than the probe's line; two are on the cartridge's own channel.</li><li>The times of a real save chip on the cartridge's channel. On the consoles that channel was answered by the flash cartridge, in its own time.</li><li>The probe with two controllers plugged in, and with a Transfer Pak. Those runs have not been made on a console.</li><li>The PIF's check that a cartridge's lockout chip is of the console's own region. It is not emulated: no cartridge is turned away.</li></ul></section>","80-saves":"<section class=\"sect n64emu-chapter\" id=\"n64emu-80-saves-sect\"><h3 class=\"sect-h\" id=\"n64emu-80-saves\">Save memory</h3>\n<p>A cartridge keeps a player's progress in a chip of its own, and which kind of chip differs from game to game. Some games save to a Controller Pak in the controller instead. The emulator has to be each of these, byte for byte, because a game that finds another chip than it expects does not save at all.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-80-saves--what-the-emulator-does\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-80-saves-s1\">1. What the emulator does</h4>\n<ul class=\"gbemu-bullets\"><li>It emulates six kinds of save memory: an EEPROM of 4 kilobits and one of 16, which answer the PIF; SRAM of 256 kilobits and of 768 kilobits in three banks, and FlashRAM of 1 megabit, which sit on the cartridge bus; and the Controller Pak, which sits in a controller.</li><li>Each kind answers as its chip does. The EEPROM is read and written in blocks of 8 bytes and is busy for a while after a write. FlashRAM takes commands, erases a sector before it writes, and says which chip it is when asked.</li><li>A cartridge has the kind its game has, and no other. A request to a chip that is not there gets no answer.</li><li>What a game saves outlives the machine. The bytes are handed to whoever runs the emulator, and a machine started later with those bytes finds them where the game left them.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> A game does not ask which chip it has. It talks to the one it was made for, and treats silence or a wrong answer as a broken cartridge.</p></div>\n<span class=\"n64emu-alt\" id=\"n64emu-80-saves--how-it-was-measured\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-80-saves-s2\">2. How it was measured</h4>\n<ul class=\"gbemu-bullets\"><li>A check writes each kind of save memory on the cartridge side from one machine and reads it in a new one. 5 of 5 kinds keep their bytes, in 81 of 81 checks.</li><li>A test program written by others tries every kind of save memory and says which it found. With each of nine fittings in turn, from none to FlashRAM, it says what it should in all of them: 9 of 9 cases. One of the nine is FlashRAM with the bus left at the speed a console starts with, where the program cannot read the chip's name and must say so.</li><li>The EEPROM in both sizes and a Controller Pak written from end to end are carried across three machines, with a fourth that is given nothing and must find nothing. 2 of 2 kinds come through.</li><li>A probe written for this emulator reads each kind on the cartridge bus, writes it and reads it again in a new machine. Its 11 runs give 341 values that are held to what is expected of them.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-80-saves--what-two-pal-consoles-said\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-80-saves-s3\">3. What two PAL consoles said</h4>\n<p>The probes of save memory ran on the first console, from a flash cartridge that stands in for each kind of chip. They show how the console's side behaves. They do not show a game cartridge's chips.</p>\n<ul class=\"gbemu-bullets\"><li>The probe of save memory did not get far. With the cartridge set to be SRAM its printout stopped after the second line, and with FlashRAM further on. The cause is the flash cartridge and not the console. The cartridge keeps its save memory in the same block of its own memory as the window through which a test sends its text, and one of the probe's first writes to save memory landed on that window's mark. The cartridge's own documents say where it keeps each, and every run stopped at the very line this predicts.</li><li>The probe now keeps its text window where the cartridge's save memory cannot reach, and the listener is told the same place. So built, it ran to its last line with the cartridge set to be each kind of save memory that was tried, 3 of 3: SRAM, SRAM in three banks, and FlashRAM.</li><li>What those printouts show beyond that is the flash cartridge's own way with save memory. Its SRAM does not repeat as a small chip does, memory that was never written reads a pattern of its own, and its FlashRAM is never busy and does not join two writes as a chip does. None of that is taken into the emulator. The three banks behaved as the emulator's do: each is written and read back whole, and the others are not changed.</li><li>A smaller probe that only reads ran through. Its one copy of 16 bytes out of SRAM ended at all the speed settings it tried, 4 of 4, the one at which the first probe seemed to stop among them.</li><li>The EEPROM behind the PIF answered as the emulator's does, and kept its bytes with the power off. Its blank bytes and its busy time are the flash cartridge's own, not a chip's.</li></ul>\n<p>Save memory does not look at the television type.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-80-saves--what-is-not-established\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-80-saves-s4\">4. What is not established</h4>\n<ul class=\"gbemu-bullets\"><li>What a real SRAM or FlashRAM chip answers to the probe of save memory. Every run so far was made from a flash cartridge, whose SRAM is wider than a chip's and does not repeat and whose FlashRAM answers in its own way, so the lines that differ show the cartridge. A game cartridge with the chip itself would settle it.</li><li>Which FlashRAM chip a game's cartridge held. Three chips were made, a game asks its chip which one it is, and the emulator tells every game the same one. A list of the chips seen in opened cartridges names that chip for 9 of the 11 games met so far whose chip the game table does not name, and for five games it reports two different chips, so one game was made with more than one. The library games are built on asks the chip and works with any of them. For the other two games nothing public names a chip. A look at the chip in such a cartridge would settle it.</li><li>How long an EEPROM stays busy after a write. Sources give different figures, and the emulator has a setting for it.</li><li>How long FlashRAM takes to erase and to write on a real chip. The emulator keeps the chip busy for the times a document gives as round figures, and the bytes themselves change at once. What a real chip holds part of the way through is not described anywhere.</li><li>A Controller Pak with more than one bank, and the Transfer Pak. Neither is emulated.</li><li>Any of this on a game cartridge's own chip. The measurements above are on the emulator; the rules come from test programs and from documents written by people who measured real chips.</li></ul></section>","90-cartridges":"<section class=\"sect n64emu-chapter\" id=\"n64emu-90-cartridges-sect\"><h3 class=\"sect-h\" id=\"n64emu-90-cartridges\">What a cartridge holds</h3>\n<p>A cartridge is more than a game. Beside the game it carries a lockout chip that the console checks before it lets anything run, a short boot code at the front of the game that sets the machine up, and for many games a chip that keeps saves. This chapter is about the first two and about the table that says which save chip each game has.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-90-cartridges--what-the-emulator-does\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-90-cartridges-s1\">1. What the emulator does</h4>\n<ul class=\"gbemu-bullets\"><li>The console's boot firmware is not part of the emulator. The emulator stands in for it: it does to the machine what the firmware does and hands the cartridge's boot code the registers the firmware hands it, which differ by television type and by lockout chip.</li><li>The cartridge's boot code then runs as it is. It sets main memory up, loads the first part of the game into it and starts the game.</li><li>The emulator knows six types of lockout chip. Each gives the boot code a seed, and the PIF holds the checksum of the boot code that belongs to it.</li><li>A cartridge's chip is named from its boot code: the tools hold the hash of each boot code they have met with the chip it belongs to, one for each of the six types. Five of the six come as a pair, one chip for each television system. The sixth has no partner: its boot code is carried by the PAL releases of one game only, and it jumps to one fixed address in place of the address the cartridge's header gives. A boot code the tools do not know is started as the commonest type, and the run's result says so.</li><li>A user who has the firmware of a console can give it to the emulator, which then runs it from the first instruction. The PIF compares the checksum the firmware works out with the lockout chip's and stops the machine when they differ, as a console does.</li><li>The firmware leaves things behind that a boot code can lean on. One boot code, the one that belongs to the lockout chip of five of the games tried, takes the first eight words the firmware leaves in the RSP's instruction memory, folds each with a word of its own by an exclusive or, and has the RSP run the result. Only with the firmware's own eight words is that a loader which brings in the boot code's RSP program; that program then copies 192 bytes of the cartridge's own boot code to 24 places in main memory, and games look for them there.</li><li>The emulator holds no byte of the firmware. A game is started in one of three ways, taken in this order. With the user's firmware, the firmware itself runs. Without it, for a cartridge that carries this boot code, the stand-in leaves eight words of its own making, which the boot code's exclusive or turns into a loader written for this emulator, and it lets the time pass that the firmware would have taken. For any other cartridge the stand-in is as it was.</li><li>That loader was written from what each of the original eight instructions is seen to do when it is run alone, never from its words. Four of the eight have one way only and so come out as the same words; the other four were written another way.</li><li>A game can put a challenge to the lockout chip while it runs. The emulator gives each type's answer; one type has a function of its own for it.</li><li>Which save chip a game has is looked up in a table by the game's own identity in its header. The table is built from two public lists and says for every row which list gave it.</li></ul>\n<div class=\"gbemu-key\"><p><b>Why.</b> A boot code is written against what the firmware leaves behind. Handing it anything else, or skipping it, makes a different machine from the first instruction on.</p></div>\n<span class=\"n64emu-alt\" id=\"n64emu-90-cartridges--how-it-was-measured\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-90-cartridges-s2\">2. How it was measured</h4>\n<ul class=\"gbemu-bullets\"><li>The hand-over is held against what the firmware gives, for every television type, every type of lockout chip, a cold start and one by the reset button, and both sizes of memory: 306 of 306 cases.</li><li>Given firmware of each of the three television types, the emulator ran each from its first instruction to the cartridge's boot code, and the registers each handed over were those of the emulator's own stand-in: 3 of 3. This runs only where a user supplies the firmware.</li><li>A game was started twice, by the stand-in and by a user's firmware, and the two machines were held against each other at the game's first instruction in 26 parts: all of main memory, both memories and every register of the RSP, the registers of every other chip, the processor's registers, and the time. Parts of what the firmware leaves were then set to zero, halves, then quarters, down to single words, to find what a game needs. Of 419 words the firmware leaves in instruction memory, 8 are needed, the same eight for each of the 5 games that carry this boot code.</li><li>Given those eight words, the time and the count of instructions, the stand-in's start is the same as the firmware's in 26 of 26 parts, for each of the five games. This runs only where a user supplies the firmware.</li><li>With its own loader and no byte of the firmware, the stand-in's start is again the same as the firmware's in 26 of 26 parts, for each of the five games. Of the loader's eight words, 4 are the same as the eight the firmware's start makes, counted without showing one.</li><li>How long the firmware takes was measured over 222 starts through a user's firmware, every game of the test set with firmware of each television type: the time is the same for every game that carries a boot code. The stand-in is given that time from a table, for every boot code the table has, so that a game started without the firmware begins when it would have begun with it. Played by script both ways, the pictures agree at every point looked at.</li><li>What the stand-in does with what it is given, and what its own loader does, is held on a test cartridge made for it, with no game and no firmware: 29 of 29 facts.</li><li>The table of games has 746 rows for 404 games, and it is rebuilt from the two lists and compared on every check. 41 of 41 lookups answer as stated.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-90-cartridges--what-two-pal-consoles-said\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-90-cartridges-s3\">3. What two PAL consoles said</h4>\n<ul class=\"gbemu-bullets\"><li>Started by its own firmware, each console handed a program the registers the emulator's stand-in hands over for a PAL console, but for one. The register that holds the firmware's version held 6 on both, where the emulator had 7. The difference is one mark that the PIF takes from the lockout chip, and a PAL console's PIF does not set it. The emulator was changed to the consoles.</li><li>A test sent the usual way is not started by the console's firmware at all. The flash cartridge's own start-up program starts it and hands over registers of its own making. On a PAL console they came out the same as the console's own, which was written down before the run for the cartridge's part.</li><li>Both consoles accepted a start by their own firmware with the flash cartridge standing in for a lockout chip.</li></ul>\n<p>What the firmware hands over depends on the television type, so this is a PAL result. For an NTSC console the emulator keeps what it had, which agrees with another emulator and with the flash cartridge's own table. None has been measured.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-90-cartridges--what-is-not-established\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-90-cartridges-s4\">4. What is not established</h4>\n<ul class=\"gbemu-bullets\"><li>What an NTSC or an MPAL console's firmware and PIF hand over, measured on a console.</li><li>The registers the firmware leaves that are not named above. They hold what its checksum last worked with; the emulator leaves them zero, as the flash cartridge's start-up program does.</li><li>A lockout chip of the wrong region. A console refuses it; the emulator does not check.</li><li>How long the firmware takes on a console before the boot code starts. The emulator's own figure for it, from running a user's firmware, rests on how long the PIF takes to answer, which no console has been asked.</li><li>For a boot code the table has no time for, a start without the firmware still begins at time zero. Measuring the firmware over a game that carries that boot code would add its row.</li><li>What the emulator's own loader does on a console. It cannot be asked: a console never holds it.</li><li>Whether a console's firmware leaves in the RSP's instruction memory what a user's firmware leaves in the emulator. The boot code that test programs carry writes over all of it before a test's first instruction; a test behind a boot code that leaves it alone would settle it.</li><li>The table of games against real cartridges. It repeats two public lists, and where they disagree the row says so.</li></ul></section>","95-scores":"<section class=\"sect n64emu-chapter\" id=\"n64emu-95-scores-sect\"><h3 class=\"sect-h\" id=\"n64emu-95-scores\">The scores</h3>\n<p>Seventeen public test suites written by others were run on the emulator, and each program's own verdict was read by a script, never by eye. This chapter gives every score, the consoles' answer to the very same file where one was asked, and plainly the places where the emulator does not pass. Its last section lists the test cartridges written for this emulator.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--what-was-run-and-how\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s1\">1. What was run, and how</h4>\n<ul class=\"gbemu-bullets\"><li>Each suite was fetched from its publisher at a fixed commit of its own repository, and every test file is known by its hash. Where the consoles ran a suite, the emulator ran the very file the consoles ran.</li><li>The emulator ran as WebAssembly, in its default build. Each program was started at its own boot code, with the memory chips not set up, as on a console.</li><li>Every suite was run three times, and the runs gave the same verdict in every suite.</li><li>The consoles' answers come from the runs on the two PAL consoles that <a href=\"#n64emu-00-machine\">The machine</a> describes, of the very same file, read by the same reader.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--the-table\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s2\">2. The table</h4>\n<div class=\"gbemu-scroll\"><table class=\"gbemu-table\"><thead><tr><th>Suite</th><th>Counted in</th><th>The emulator</th><th>Two PAL consoles</th></tr></thead><tbody><tr><td>nemu64-test, base level</td><td>cases (the suite's own count)</td><td>4,637 of 4,637</td><td>4,637 of 4,637, in 2 runs</td></tr><tr><td>nemu64-test, built for 4 MiB</td><td>cases (the suite's own count)</td><td>4,637 of 4,637</td><td>4,637 of 4,637, in 3 runs</td></tr><tr><td>nemu64-test, timing and cycle levels</td><td>cases (the suite's own count, timing and cycle levels)</td><td>1,607 of 1,617</td><td>1,613 to 1,614 of 1,617, in 2 runs</td></tr><tr><td>nemu64-test, COP0 hazard level</td><td>cases (the suite's own count)</td><td>2 of 5</td><td>not run on these consoles</td></tr><tr><td>The open library's tests</td><td>tests (its own count, skipped tests left out)</td><td>213 of 224</td><td>210 to 213 of 225, in 9 runs</td></tr><tr><td>n64_pi_dma_test</td><td>rows of 383 transfers each, judged by the program</td><td>64 of 64</td><td>not run on these consoles</td></tr><tr><td>rsp_inval_instrs</td><td>program verdict</td><td>1 of 1</td><td>1 of 1, in 1 run</td></tr><tr><td>N64-IntegerMulDiv-Test</td><td>cases its model covers (MULT and DIV)</td><td>1,499,479 of 1,499,479</td><td>1,499,479 of 1,499,479, in 1 run</td></tr><tr><td>n64-tests by Dillonb</td><td>programs pass</td><td>26 of 26</td><td>not run on these consoles</td></tr><tr><td>N64-CPU-Tests</td><td>files the same as the console's</td><td>30 of 30</td><td>not run on these consoles</td></tr><tr><td>krom's processor tests</td><td>programs with a verdict (PASS or FAIL drawn in the program's own fonts)</td><td>95 of 97</td><td>not run on these consoles</td></tr><tr><td>krom's RSP tests</td><td>programs with a verdict (PASS or FAIL drawn in the program's own fonts)</td><td>54 of 55</td><td>see its section</td></tr><tr><td>The RSP goldens</td><td>cases</td><td>1,380 of 1,380</td><td>not run on these consoles</td></tr><tr><td>snapper64</td><td>tests the same as the console's snapshots</td><td>5,265 of 6,632</td><td>not run on these consoles</td></tr><tr><td>SaveTest-N64</td><td>rows right</td><td>72 of 72</td><td>not run on these consoles</td></tr><tr><td>The controller programs</td><td>judged rows pass</td><td>25 of 25</td><td>not run on these consoles</td></tr><tr><td>n64-systemcrash</td><td>crash cases (the program's own count: a case passes when the machine does not come back from it)</td><td>24 of 29</td><td>not run on these consoles</td></tr></tbody></table></div>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--where-the-emulator-is-not-clean\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s3\">3. Where the emulator is not clean</h4>\n<ul class=\"gbemu-bullets\"><li><b>The timing level of nemu64-test.</b> 10 of its 1,617 checks fail, in two tests: Timing: Load Miss (with VI enabled) and Timing: Load Miss (with VI disabled). In the second, the emulator's reads that miss the cache come out about one cycle short of the 42.5 cycles the suite expects. The first fails on both consoles as well.</li><li><b>snapper64.</b> 1,367 of its 6,632 tests differ from the console's snapshots, all in four groups: triangles in fill mode made at random (7 of 7) and in a sweep (1,124 of 2,048), rectangles filled without a sync between them (20 of 20), and triangles in the span test mode (216 of 216).</li><li><b>The COP0 hazard level of nemu64-test</b>, which the suite's default build leaves out. 3 of its 5 checks fail: SoftwareInterrupt1 (enabled, hazard), SoftwareInterrupt1 (enable but disable right away) and SoftwareInterrupt12 (enable and disable after one nop). In each the Cause register reads 0x8100 where the suite expects 0x100. No console has run this build, so these three are not settled against hardware.</li><li><b>n64-systemcrash.</b> Of its 29 cases in which a console freezes, 24 freeze the emulator too. The five that do not are all the RDP's: FILL on 4bpp, COPY on 32bpp, FILL with READEN, FILL with ZCMP and FILL with ZUPD. There the emulator draws where a console's RDP hangs. The cases are the program's author's; no console here has run it.</li><li><b>The open library's tests.</b> 11 of 224 fail: test_ticks, test_timer_oneshot, test_timer_slow_callback, test_timer_continuous, test_timer_continuous_short, test_timer_mixed, test_timer_context, test_timer_disabled_start, test_dfs_rom_addr, test_dfs_rom_size and test_cache_invalidate. All 11 fail on a console as well, in one of its runs of the very same file.</li><li><b>krom's processor tests.</b> 2 of the 97 programs that draw a verdict fail, its two timing programs CP1TIMINGNTSC and CPUTIMINGNTSC.</li><li><b>The time a fill takes.</b> In a single run of the fill program of RDP-Timing-Tests, by Thar0, the emulator takes the same time for every fill whatever the memory traffic, where its author's console takes from 1.24 to 4.14 ms.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--nemu64-test-base-level\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s4\">4. nemu64-test, base level</h4>\n<p>The successor of n64-systemtest, by thelemmy and contributors, under the MIT licence. Its base level asks for the processor, its COP0 and COP1, the TLB, the caches, exceptions, the MI, the PI, the RSP's DMA, the PIF's memory, the memory chips' registers, the RSP's scalar and vector units and some of the RDP. The emulator passes 4,637 of 4,637 checks. What the consoles said is in <a href=\"#n64emu-00-machine\">The machine</a>.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--nemu64-test-built-for-4-mib\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s5\">5. nemu64-test, built for 4 MiB</h4>\n<p>The same suite built to fit 4 MiB, its heap ending at 3 MiB in place of 7, and run with 4 MiB: the suite as fetched needs 8 MiB, as <a href=\"#n64emu-05-memory\">Main memory</a> says. The emulator passes 4,637 of 4,637, and so did the consoles in all three runs of the very same file.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--nemu64-test-timing-and-cycle-levels\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s6\">6. nemu64-test, timing and cycle levels</h4>\n<p>The same suite with its timing and cycle levels, which time instructions and the bus: 1,617 checks. The emulator passes 1,607, and section 3 says which fail. The consoles passed 1,614 and 1,613. They fail Timing: Load Miss (with VI enabled), Timing: Load from uncached (with VI enabled) and RSP Timing: Clock CPU vs RDP, and the emulator passes the last two.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--nemu64-test-cop0-hazard-level\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s7\">7. nemu64-test, COP0 hazard level</h4>\n<p>The level of the same suite that tests what COP0 does in the cycles right after a write to it. The emulator passes 2 of 5; section 3 names the three that fail. The other emulator run on it passes none of them.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--the-open-library-s-tests\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s8\">8. The open library's tests</h4>\n<p>libdragon's own test program, by the libdragon project, under the Unlicense: timers, exceptions, DMA, the caches, the file system, the RSP's queue, the RDP layer and the decoders. The emulator passes 213 of 224, the program's own count with its skipped tests left out. The consoles ran the very same file in nine runs and passed 210 to 213 of 225. A console counts one test more, because it runs from a flash cartridge with an SD card and the program's test of that card runs there, where every emulator here skips it. Which timer tests fail varies from run to run on a console.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--n64-pi-dma-test\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s9\">9. n64_pi_dma_test</h4>\n<p>By rasky; its repository states no licence, so it is run here and not served. It makes PI DMA transfers of every size and alignment, 24,512 transfers in 64 rows, and holds memory, the registers and the time to a console's recordings. The emulator passes 64 of 64 rows.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--rsp-inval-instrs\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s10\">10. rsp_inval_instrs</h4>\n<p>By sauraen, under the Unlicense: the RSP's unused SPECIAL encodings. The emulator passes, and so did a console.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--n64-integermuldiv-test\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s11\">11. N64-IntegerMulDiv-Test</h4>\n<p>By Thar0, under CC0 1.0: MULT and DIV with operands that are not sign-extended, a million cases each. The emulator agrees with the program's model in all 1,499,479 cases the model covers, as a console did: 1,000,000 of MULT and 499,479 of DIV. The other 500,521 divides fall outside the program's model.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--n64-tests-by-dillonb\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s12\">12. n64-tests by Dillonb</h4>\n<p>26 programs for bringing up a processor, 100,000 cases a group, each leaving its verdict in a register; the repository states no licence. The emulator passes 26 of 26.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--n64-cpu-tests\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s13\">13. N64-CPU-Tests</h4>\n<p>By Thar0, under CC BY-SA 4.0: single processor instructions, each file's final memory held to a console's. 30 of 30 files come out the same as the console's.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--krom-s-processor-tests\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s14\">14. krom's processor tests</h4>\n<p>By PeterLemon (krom), under the Unlicense for the source: programs of the processor, COP0, COP1 and timing that draw PASS or FAIL. 95 of 97 programs that draw a verdict pass, and section 3 names the two that fail. 17 programs draw no word: the 16 tables of floating-point compares, and COP1FullMode.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--krom-s-rsp-tests\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s15\">15. krom's RSP tests</h4>\n<p>By the same author, programs of the RSP that draw PASS or FAIL. 54 of 55 pass. The one that fails, CP2/RESERVED/V073, fails the same 4 checks as two PAL consoles do, so there the emulator gives the consoles' answer. One more program, RSPXBUSRDP, draws no word.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--the-rsp-goldens\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s16\">16. The RSP goldens</h4>\n<p>Published by rasky, under GPL-3.0 for the repository: the outputs of every group of the RSP's vector operations, recorded on a console through a 64drive. The emulator gives 1,380 of 1,380 cases, in 47 of 47 groups.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--snapper64\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s17\">17. snapper64</h4>\n<p>By HailToDodongo, under the MIT licence: 13 groups of RDP tests held to the snapshots a console took, 6,632 tests and 7,094 snapshots. The emulator gives 5,265 of 6,632 tests the same as the console, and section 3 lists the four groups that differ. <a href=\"#n64emu-30-rdp\">The RDP</a> counts the same suite by its snapshots, not by its tests.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--savetest-n64\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s18\">18. SaveTest-N64</h4>\n<p>By meeq, under the Unlicense: every kind of save memory. 72 of 72 rows come out right, in 9 of 9 kinds.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--the-controller-programs\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s19\">19. The controller programs</h4>\n<p>JoypadTest-N64 by meeq (the Unlicense), n64_controller_test by Ryzee119 (MIT) and krom's Input programs (the Unlicense). 25 of 25 judged rows pass; 6 more are shown and not judged.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--n64-systemcrash\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s20\">20. n64-systemcrash</h4>\n<p>By rasky; its repository states no licence. 29 cases in which a console freezes, the program keeping its place in save memory across power cycles; it was built here with one change to the copy, so that the compiler used here takes it. 24 of 29 freeze the emulator, and section 3 names the five that do not.</p>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--what-has-no-verdict-yet\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s21\">21. What has no verdict yet</h4>\n<ul class=\"gbemu-bullets\"><li><b>rsp-ruination</b>, by Dillonb, which holds the RSP's vector unit to a model on the processor: 32,768 cases without a difference. That is a budget of instructions, not a whole round of the program.</li><li><b>n64-systembench</b>, by hacktarux, whose rows of bus, cache, DMA and controller costs are held to the console's figures in its source: 39 of 39 rows within one cycle or 3% of the console's figure, and 21 exactly. The judging is this emulator's tolerance, not the program's.</li><li><b>The stress builds of nemu64-test</b> are not judged. One run of its math build was stopped at 35 minutes with no verdict, and its multiply build was not run: by the suite's own notes each of its 13 tests takes about 80 minutes on a console.</li><li><b>krom's 16 tables of floating-point compares</b> draw no word, so they were judged instead against the rule of the processor's manual: 784 of 784 cells agree. COP1FullMode is not judged.</li><li><b>The time a fill takes</b> rests on a single run, so it is one reading, not a measurement.</li></ul>\n<span class=\"n64emu-alt\" id=\"n64emu-95-scores--our-test-cartridges\"></span><h4 class=\"gbemu-sub\" id=\"n64emu-95-scores-s22\">22. Our test cartridges</h4>\n<p>Beside the public suites, the emulator was measured with test cartridges written for it, which this chapter's other sections do not count: the 49 test cartridges below. Each asks the console one question and prints the answer as lines of text, which a flash cartridge passes to a computer; an emulator's debug window prints them too. With one exception they do not judge themselves: the printout is set beside a console's, line by line. The consoles' answers they are held to come from two PAL consoles only. No NTSC console has run them, so an NTSC console's answer may differ wherever the television type matters.</p>\n<p>Some of them do what an ordinary program never does, and the table says so. Read it before running one on a console.</p>\n<div class=\"gbemu-scroll\"><table class=\"gbemu-table\"><thead><tr><th>Test cartridge</th><th>What it asks</th><th>Console runs</th><th>Take care</th></tr></thead><tbody><tr><td>ai-cut</td><td>What the AI does when its bit rate is written zero while a transfer plays: length, status and interrupt at once and later, with one and two transfers queued, the rate restored, a rate of one, transfers after a cut, and the sample counter about the rate's return; each case three times.</td><td>7, both consoles</td><td></td></tr><tr><td>ai-level</td><td>Four short sounds with half a second of nothing after each, for a sound recorder: what the DAC is fed when the AI has nothing to play, which no register shows.</td><td>none</td><td>Turn the television's sound down first: it plays four short sounds for a sound recorder.</td></tr><tr><td>ai-registers</td><td>The AI's registers: when its interrupt comes, what the length reads during play, what a length written at an odd moment does, the true sample period.</td><td>7, console one</td><td></td></tr><tr><td>ai-tone</td><td>A second and a half of square waves (near 450 Hz left, an octave lower right on PAL) and one line of how long it took by the CPU clock, so pitch and length show which clock timed the AI.</td><td>2, both consoles</td><td>It is loud, square waves at a quarter of full level, so turn the sound down first.</td></tr><tr><td>armed-fetch</td><td>Nine cases that fetch, or do not fetch, a line of instructions from main memory with the MI's repeat mode armed, each saying which instructions the CPU ran.</td><td>1, console one</td><td>It reads memory in a test mode that may hang a console; if it stops, switch the console off and keep the printout.</td></tr><tr><td>armed-fill</td><td>Which words a cache fill gets from main memory with the repeat mode armed, for the instruction and data caches at each count, with a control.</td><td>2, console one</td><td>It reads memory in a test mode that may hang a console; if it stops, switch the console off and keep the printout.</td></tr><tr><td>cpu-align</td><td>Where the CPU is called away by an RCP interrupt that a store asks for: the routine at eight places of its instruction line, after each kind of bus wait (register, RSP memory, main memory, a data line, the Fill operation) with cycle counts, a store before the asking store, the interrupt through the MI mask, Cause and COUNT read behind the store.</td><td>4, both consoles</td><td></td></tr><tr><td>cpu-pairs</td><td>What the instruction right behind a store through the data cache waits for (uncached read, cached load, second store, with and without one idle instruction, at three places against the RCP clock).</td><td>4, both consoles</td><td></td></tr><tr><td>cpu-phase</td><td>Where the CPU stands against the RCP clock after waiting for it: interrupt lines after an uncached MI read, with a store to the MI mask first, and 16 stores and reads of RSP registers in a row.</td><td>4, both consoles</td><td></td></tr><tr><td>cpu-rows</td><td>What a line of instructions costs when the memory chip has another row open, asked for by the Fill operation and by running into the line, 0 to 40 idle instructions behind each kind of read.</td><td>2, console one</td><td>It only reads and times.</td></tr><tr><td>cpu-time</td><td>The cycles to enter an exception and an interrupt, the cost of each CACHE operation, when the timer bit shows, whether a jump waits after a load, and 2,048 single reads with the VI off.</td><td>5, both consoles</td><td></td></tr><tr><td>cpu-tries</td><td>The cpu-time probe printing all eight tries of each timed piece, with its RCP interrupt lines remade so that the wait before the CPU sees the line rise is read directly.</td><td>3, both consoles</td><td></td></tr><tr><td>cpu-waits</td><td>Where the CPU stands after running into an uncached instruction line (row open or not), an interrupt during that wait, COUNT behind two reads, how long a written-back line holds the bus, a read behind a store.</td><td>4, both consoles</td><td></td></tr><tr><td>current</td><td>A memory chip's output current: on the second 2 MiB chip, at each of 64 steps set by hand, how many one bits come back; the step the chip settles at when it regulates; then it sets a working step back.</td><td>none</td><td>It drives a memory chip at current settings that a boot code never leaves it at, and it has never run on a console; switch the console off as soon as it ends.</td></tr><tr><td>dcache-line</td><td>A data cache line written back over bytes stored without the cache: the steps by which the rsp-ruination pair test damages its own RSP code on emulators but not on a console, walked in the open, and what memory and the RSP's DMA then hold.</td><td>3, both consoles</td><td></td></tr><tr><td>divide</td><td>DIV and DIVU with 64-bit register operands that are not sign-extended 32-bit values, walked over the half of cases where bits 63 and 31 of the divisor differ.</td><td>3, both consoles</td><td></td></tr><tr><td>dp-depth</td><td>How many commands the DP takes in ahead of the drawing: one large fill and 120 commands behind it, CURRENT and STATUS read 24 times, three runs of each.</td><td>5, both consoles</td><td></td></tr><tr><td>dp-pace</td><td>The pace at which the DP reads a list into its buffer, CURRENT or STATUS read at every count of idle instructions up to 1,535, then a second list during a long first, and FREEZE and FLUSH while drawing.</td><td>2, both consoles</td><td></td></tr><tr><td>dp-queue</td><td>A second DP list handed over straight after a first, with the first over at once or still drawing; status and CURRENT after each write and whether both lists' marks are in memory.</td><td>9, both consoles</td><td></td></tr><tr><td>dp-reach</td><td>How far back a setting changed without a sync reaches into drawing already queued: 42 short lists, six pixels each, twice.</td><td>5, both consoles</td><td></td></tr><tr><td>dp-time</td><td>What the CPU can see of the RDP's time: for 24 short lists the DP status, the full sync's interrupt time, the busy counters, and which lines of a large rectangle reach memory on the way.</td><td>2, both consoles</td><td></td></tr><tr><td>fill-8</td><td>What the RDP writes when it fills into an 8-bit colour image: 296 runs at four start addresses over hidden bits laid clear or set; 32 bytes and their hidden bits per line.</td><td>2, both consoles</td><td></td></tr><tr><td>fill-8-span</td><td>The rule of the 8-bit fill: 344 runs into 64 bytes, at each of eight starts in a group of eight bytes, runs of one to three groups, into a second line, and a 16-bit image off a multiple of eight.</td><td>4, both consoles</td><td></td></tr><tr><td>frames</td><td>A film of known RDP frames with no end, the known answer for this emulator's frame recorder.</td><td>none</td><td>A tool for testing an emulator's frame recorder, not a question for a console.</td></tr><tr><td>hidden-bits</td><td>The ninth bit beside each byte of main memory: what stores of each size, a written-back cache line, the repeat mode and each kind of DMA leave there, and the DP clock against the CPU counter.</td><td>3, both consoles</td><td>It turns on the MI's test mode for one read at a time.</td></tr><tr><td>load-4</td><td>Loads given while the texture image is set to 4 bits a texel: eleven loads, all of texture memory drawn out in copy mode after each.</td><td>2, both consoles</td><td>The console's RDP hangs at this load, and the console must be switched off and on again.</td></tr><tr><td>load-4-block</td><td>Loads given while the texture image is set to 4 bits a texel: eleven loads, all of texture memory drawn out in copy mode after each.</td><td>2, both consoles</td><td>The console's RDP hangs at this load, and the console must be switched off and on again.</td></tr><tr><td>load-4-palette</td><td>Loads given while the texture image is set to 4 bits a texel: eleven loads, all of texture memory drawn out in copy mode after each.</td><td>2, both consoles</td><td>The console's RDP hangs at this load, and the console must be switched off and on again.</td></tr><tr><td>pad-film</td><td>A known picture and a known tone driven by controller 1, read once per field as a game reads it, for this site's play page.</td><td>none</td><td>It writes nothing to a pak or to save memory.</td></tr><tr><td>pak-check</td><td>Reads all 1,024 blocks of a Controller Pak and prints verdicts and checksums: the identity block in four places, the index table and copy, the notes and their chains, free and lost pages, a checksum per page.</td><td>2, console one</td><td>It only reads the Controller Pak in controller 1, but its printout describes what that pak holds, so keep the printout private.</td></tr><tr><td>pi</td><td>The PI: DMA from memory out to the cartridge bus, timings, a second transfer while busy, the address registers during a transfer, the disk drive registers' timing.</td><td>2, console one</td><td>It overwrites the first 4 KiB of the cartridge's save memory: run it only with a blank save.</td></tr><tr><td>pi-odd</td><td>The PI's odd cases: 156 transfers from misaligned memory addresses, seven lengths timed both ways at four timings, when a transfer ends by one look, and the address register after a reset during a transfer.</td><td>7, both consoles</td><td>It overwrites the first 8 KiB of the cartridge's save memory: run it only with a blank save.</td></tr><tr><td>repeat-read</td><td>What a read gives straight after a store in the MI's repeat mode, the cause of the hidden-bits probe's lost letter.</td><td>2, console one</td><td></td></tr><tr><td>rsp-behind</td><td>What the rest of the machine sees of an RSP in the middle of a long run (PC reads, single step, DMAs the RSP does not wait for, the DP reading from RSP memory, writes ahead of the running RSP).</td><td>none</td><td></td></tr><tr><td>rsp-blocks</td><td>An RSP that comes to the same instructions in other states (code overwritten by DMA, by the CPU, delay-slot loads).</td><td>none</td><td></td></tr><tr><td>rsp-dma</td><td>How long the RSP's DMA takes, timed by the RSP itself reading its busy mark, so the CPU's bus times are left out.</td><td>2, both consoles</td><td></td></tr><tr><td>rsp-unnamed</td><td>The RSP's vector operations with no name, run straight after a vector load, in the cases where four older test programs and n64-systemtest contradict each other.</td><td>3, both consoles</td><td></td></tr><tr><td>save</td><td>The cartridge save memory set to one kind before the start (SRAM, three banked SRAM chips, FlashRAM): what it holds, writes, what it holds after a power-off.</td><td>7, console one</td><td>It erases and overwrites the whole of the cartridge's save memory, FlashRAM included: never run it over a save that matters.</td></tr><tr><td>save-step</td><td>The one 16-byte SRAM read at which the save probe stopped on a console, at four timings, each step said before it is taken and given up after about 50 ms.</td><td>3, console one</td><td>It only reads the cartridge's save memory.</td></tr><tr><td>save-trace</td><td>The save probe built to print a line before and after each DMA and to give up on one that does not end, to find where the save probe stopped.</td><td>3, console one</td><td>It overwrites the cartridge's save memory, as the save probe does: never run it over a save that matters.</td></tr><tr><td>si-joybus</td><td>The SI and PIF: registers handed over by the boot firmware, PIF memory, end-of-boot, joybus frame rules (padding, end mark, reset, skip, too many and too few bytes), what empty ports answer, a pak read with right and wrong address checks, a save chip read, a transfer during another, and times.</td><td>17, both consoles</td><td>It only reads, but its printout shows four bytes of the Controller Pak in controller 1, and it leaves the SI's error mark set until the console is switched off.</td></tr><tr><td>si-pak</td><td>A controller's pak: whether a pak in from power-on answers before the first identity command, what lies past a Controller Pak's end, whether wrong address checks are answered, times, a pak pulled and pushed by hand, a write only when the controller says no pak is in.</td><td>23, both consoles</td><td>When the controller says no pak is in, it sends one write of 32 zero bytes to the pak's address 0x8000, which is not Controller Pak memory.</td></tr><tr><td>si-save</td><td>Whether what is written to the cartridge's serial save chip (4 or 16 kilobit) and to a Controller Pak is still there at the next start: before, write, after, run twice across a power-off.</td><td>3, console one</td><td>It writes every block of the cartridge's serial save chip and the first 32 bytes of a Controller Pak in controller 1 on every run, and with Z held at the start it overwrites the whole pak: never run it with a pak or a save that matters.</td></tr><tr><td>span-modes</td><td>Draws in every RDP mode a span loop of the emulator is made for, with made-up triangle coefficients, for the check that holds a faster build to the plain one.</td><td>none</td><td>Written for emulators and not for a console: no one has checked that a console takes its lists.</td></tr><tr><td>startup</td><td>What the boot code leaves behind: the RI's registers, every register of every memory chip, how much memory answers, what a read above fitted memory gives.</td><td>8, both consoles</td><td>It writes nothing to the memory chips' registers.</td></tr><tr><td>vi-first</td><td>How long after the VI is switched on its interrupt line shows in the MI, with a PAL low-resolution mode: the smallest loop count at which it is up, three times over.</td><td>3, both consoles</td><td></td></tr><tr><td>vi-lines</td><td>The VI: registers at start, writable bits, line length by COUNT, the line counter across field ends (525 and 526 half-lines), field bit, counter when the VI is turned on, the line interrupt, and how much the picture slows memory reads.</td><td>5, both consoles</td><td>It never sets bit 5 of the VI's control register, and it turns the VI off before every change it makes.</td></tr><tr><td>wait-loop</td><td>What a program sees when it waits for an interrupt in a two-instruction loop, as games do, for every interrupt source and loop form, including a loop on a page reached through the TLB.</td><td>none</td><td>Written for emulators: it leaves the TLB as it finds it and sets an NTSC picture timing, and it has not been tried on a console.</td></tr><tr><td>window-state</td><td>The flash cartridge's debug text window: what the cartridge is set to when a test begins, and whether a word written at the window's start reads back (how libdragon decides it has a text sink).</td><td>2, console one</td><td>A test of the flash cartridge rather than the console: it changes two of the cartridge's settings, which are forgotten when the power is cut, and writes four words at its debug window.</td></tr></tbody></table></div>\n<div class=\"n64emu-tests\"><h5 class=\"gbemu-sub\" id=\"n64emu-95-scores--test-programs-you-can-run\">Test programs you can run</h5>\n<p>The public test suites the scores come from are their authors' own and are not published with this guide. Our Nintendo 64 test cartridges are, with the real console's answers:</p>\n<p><b>Download</b> (a separate file on this site, not part of this page's text): <a href=\"/downloads/n64-tests/n64-test-cartridges.zip\" download>all 49 test cartridges in one zip</a>, MIT licence, with their C and assembly source, a read-me for each and each one's expected answers. The first 4 KB of every test file is libdragon's open boot code, under its own licence, the Unlicense.</p>\n<p>Each asks a real console one question the public suites leave out: the processor's timing and caches (10), main memory and its interface (6), the RSP (4), the drawing unit (12), the audio interface (4), the video interface (2), the parallel interface and save memory (6), and the serial interface, the controllers and the Controller Pak (5).</p>\n<ul class=\"gbemu-bullets\"><li>How a test answers: none shows a verdict on the screen. Each prints lines of text on the debug text window (a ring of bytes marked IS64, at cartridge address 13FF0000 unless its source places it elsewhere), which a flash cartridge such as the SummerCart64 passes to the computer beside the console and which some emulators print.</li><li>Expected result: the console's own lines, in each test's <code>expected-answers.json</code>. 41 of the 49 have them, from two PAL consoles; an NTSC console has not been run yet, so the lines that depend on the television type may differ on one. Eight have no console answers yet: the three made for emulators, the one never run on a console, and four more.</li><li>Take care on a real console, as each test's read-me says first: five can hang a console (armed-fetch, armed-fill, and load-4, load-4-block and load-4-palette, which always stop the drawing unit until the console is switched off); six write to save memory or a Controller Pak (si-save, save, save-trace, pi, pi-odd, and si-pak, which can send one write to a pak); current has never been run on a console; span-modes, wait-loop and frames are for emulators only.</li></ul></div></section>"},"hero":{"score":"10 of 17","date":"21 Nov 2026","scoreOn":"public test suites passed in full","title":"The Nintendo 64, part by part, as our core runs it","blurb":"The processor, the RSP, the RDP, the VI, the AI, the PI, the SI and the PIF, main memory, save memory and the cartridge, each as the console does it, and each measured against two PAL consoles. Every statement says in words how it is known, and each chapter says what is not established. The last chapter gives the score of every public test suite."}};

/* The chapter anchors, in reading order. */
var n64EmulationAnchors = N64_EMU.order.map(function (u) { return "n64emu-" + u; });

/* The Emulation tab for a Nintendo 64 drawer (d.catalogue 'n64', or d.system 'n64'); '' for
 * anything else. */
function n64EmulationTabHTML(d) {
  if (!d || (d.catalogue !== "n64" && d.system !== "n64")) return "";
  var e = function (s) { return String(s).replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;"); };
  var H = N64_EMU.hero, O = N64_EMU.order;
  var h = '<section class="gbemu-hero"><div class="gbemu-hero-num"><b>' + e(H.score) + '</b><span>' + e(H.scoreOn) + ', ' + e(H.date) + '</span></div>' +
    '<div class="gbemu-hero-txt"><h3>' + e(H.title) + '</h3><p>' + e(H.blurb) + '</p></div></section>\n' +
    '<nav class="gbemu-toc"><b>Nintendo 64</b> ';
  for (var j = 0; j < O.length; j++) h += '<a href="#n64emu-' + O[j] + '">' + e(N64_EMU.titles[O[j]]) + '</a> ';
  h += '</nav>';
  for (var k = 0; k < O.length; k++) h += "\n" + N64_EMU.units[O[k]];
  return '<div class="gbemu n64emu" id="n64emu-guide">' + h + '</div>';
}
